-- =====================================================================
--  Grape Arts · קובץ הקמה למסד הנתונים (Supabase)
--  מדביקים את כל הקובץ ב-SQL Editor ולוחצים Run. אפשר להריץ שוב בבטחה.
-- =====================================================================

create extension if not exists pgcrypto;

-- ---------- סוגים ----------
do $$ begin
  create type app_role   as enum ('winery','artist','gallery','curator','printer','admin');
exception when duplicate_object then null; end $$;
do $$ begin
  create type deal_status as enum ('sent','priced','sign','pay','active','rejected','cancelled');
exception when duplicate_object then null; end $$;
do $$ begin
  create type work_status as enum ('pending','review','live','paused','rejected');
exception when duplicate_object then null; end $$;

-- ---------- 1. הגדרות מערכת ----------
create table if not exists settings (
  id          int primary key default 1 check (id = 1),
  vat_pct     numeric not null default 18,
  comm_min    numeric not null default 15,
  comm_max    numeric not null default 20,
  artist_share numeric not null default 50,
  render_quota int not null default 6,
  updated_at  timestamptz not null default now()
);
alter table settings add column if not exists comm_pct numeric not null default 15;
insert into settings (id) values (1) on conflict do nothing;

-- ---------- 2. ארגונים (יקב, גלריה, בית דפוס, הפלטפורמה) ----------
create table if not exists organizations (
  id         uuid primary key default gen_random_uuid(),
  kind       app_role not null check (kind in ('winery','gallery','printer','curator','admin')),
  name       text not null,
  city       text,
  site       text,
  phone      text,
  comm_pct   numeric check (comm_pct between 0 and 40),   -- עמלת גלריה
  active     boolean not null default true,
  created_at timestamptz not null default now()
);

-- ---------- 3. משתמשים ----------
create table if not exists profiles (
  id         uuid primary key references auth.users(id) on delete cascade,
  email      text,
  phone      text,
  full_name  text,
  role       app_role,                 -- נקבע על ידי מנהל המערכת
  org_id     uuid references organizations(id),
  status     text not null default 'pending' check (status in ('pending','active','blocked')),
  seen_intro text[] not null default '{}',
  created_at timestamptz not null default now()
);

-- ---------- 4. אמנים ----------
create table if not exists artists (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid unique references profiles(id) on delete set null,
  gallery_id uuid not null references organizations(id),
  name       text not null,
  bio        text,
  instagram  text,
  floor_price numeric not null default 3500,   -- מחיר רצפה לרישיון בסיסי, לפני מע״מ
  restrict_text text,                            -- שימושים שאינם מותרים
  restrict_tags text[] not null default '{}',
  created_at timestamptz not null default now()
);

alter table artists add column if not exists country text not null default 'ישראל';

-- ---------- 5. יצירות ----------
create table if not exists works (
  id         bigint generated by default as identity primary key,
  artist_id  uuid not null references artists(id) on delete cascade,
  title      text not null,
  year       int,
  size       text,
  tag        text,
  tone       text,
  status     work_status not null default 'pending',
  available  boolean not null default true,
  pick_rank  int,                 -- סדר הבחירה של האוצרות
  no_crop    jsonb not null default '{}',   -- אזורים שאסור לחתוך
  image_path text,                -- נתיב בתוך דלי works
  review_note text,
  created_at timestamptz not null default now()
);

-- ---------- 6. יינות ----------
create table if not exists wines (
  id         bigint generated by default as identity primary key,
  winery_id  uuid not null references organizations(id) on delete cascade,
  name       text not null,
  vintage    int,
  type       text not null check (type in ('red','white','rose','sparkling','dessert','other')),
  bottles    int,
  created_at timestamptz not null default now()
);

-- ---------- 7. עיצובים (יין × יצירה) ----------
create table if not exists designs (
  code       text primary key,
  wine_id    bigint not null references wines(id) on delete cascade,
  work_id    bigint not null references works(id),
  pos        int not null default 50,
  zoom       int not null default 100,
  layout     jsonb not null default '{}',
  created_by uuid references profiles(id),
  created_at timestamptz not null default now()
);

-- ---------- 8. עסקאות (בקשת רישיון) ----------
create table if not exists deals (
  id          bigint generated by default as identity (start with 1000) primary key,
  winery_id   uuid not null references organizations(id),
  gallery_id  uuid not null references organizations(id),
  artist_id   uuid not null references artists(id),
  work_id     bigint not null references works(id),
  wine_id     bigint references wines(id),
  design_code text references designs(code),
  wine_label  text,
  license_type text not null check (license_type in ('one','series')),
  qty_tier    text not null check (qty_tier in ('a','b','c')),
  exclusive   boolean not null default false,
  adj_pct     int not null default 0 check (adj_pct between -15 and 15),
  comm_pct    numeric,
  price_net   numeric,          -- לפני מע״מ, נקבע בתמחור
  status      deal_status not null default 'sent',
  note        text,
  signed_at   timestamptz,
  paid_at     date,
  ends_at     date,
  created_by  uuid references profiles(id),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- ---------- 9. הודעות בחדר העסקה ----------
create table if not exists deal_messages (
  id         bigint generated by default as identity primary key,
  deal_id    bigint not null references deals(id) on delete cascade,
  sender     uuid not null default auth.uid() references profiles(id),
  sender_role app_role,
  body       text not null check (length(body) between 1 and 2000),
  created_at timestamptz not null default now()
);

-- ---------- 10. חוזים ----------
create table if not exists contracts (
  id         bigint generated by default as identity primary key,
  deal_id    bigint not null unique references deals(id) on delete cascade,
  terms      jsonb not null,
  pdf_path   text,
  signed_by  uuid references profiles(id),
  signed_at  timestamptz,
  created_at timestamptz not null default now()
);

-- ---------- 11. חשבוניות ותשלומים ----------
create table if not exists invoices (
  id         bigint generated by default as identity (start with 1001) primary key,
  deal_id    bigint not null unique references deals(id) on delete cascade,
  net        numeric not null,
  vat        numeric not null,
  total      numeric not null,
  number     text,
  confirmed_by uuid references profiles(id),
  confirmed_at timestamptz,
  created_at timestamptz not null default now()
);

-- ---------- 12. הדמיות ----------
create table if not exists renders (
  id         bigint generated by default as identity primary key,
  deal_id    bigint references deals(id) on delete cascade,
  design_code text references designs(code) on delete cascade,
  image_path text,
  approved   boolean,           -- null = ממתין לבדיקה
  reviewed_by uuid references profiles(id),
  created_by uuid references profiles(id),
  created_at timestamptz not null default now()
);

-- ---------- 13. הזמנות דפוס ----------
create table if not exists print_orders (
  id         bigint generated by default as identity primary key,
  deal_id    bigint not null unique references deals(id) on delete cascade,
  printer_id uuid references organizations(id),
  stage      int not null default 1 check (stage between 1 and 4),
  qty        int,
  due        date,
  files_path text,
  created_at timestamptz not null default now()
);

-- ---------- 14. בקשות הצטרפות (גלריות, יקבים) ----------
create table if not exists applications (
  id         bigint generated by default as identity primary key,
  kind       app_role not null,
  name       text not null,
  details    text,
  site       text,
  why        text,
  contact    text,
  status     text not null default 'new' check (status in ('new','approved','rejected')),
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);

-- ---------- 15. התראות ----------
create table if not exists notifications (
  id         bigint generated by default as identity primary key,
  user_id    uuid not null references profiles(id) on delete cascade,
  deal_id    bigint references deals(id) on delete cascade,
  body       text not null,
  read_at    timestamptz,
  created_at timestamptz not null default now()
);

-- ---------- 16. יומן פעולות ----------
create table if not exists audit_log (
  id         bigint generated by default as identity primary key,
  actor      uuid default auth.uid(),
  action     text not null,
  entity     text,
  entity_id  text,
  data       jsonb,
  created_at timestamptz not null default now()
);

create index if not exists deals_winery_idx  on deals(winery_id);
create index if not exists deals_gallery_idx on deals(gallery_id);
create index if not exists deals_artist_idx  on deals(artist_id);
create index if not exists works_artist_idx  on works(artist_id);
create index if not exists msgs_deal_idx     on deal_messages(deal_id);
create index if not exists notif_user_idx    on notifications(user_id, read_at);

-- =====================================================================
--  פונקציות עזר להרשאות
-- =====================================================================
create or replace function my_role() returns app_role
language sql stable security definer set search_path = public as $$
  select role from profiles where id = auth.uid() and status = 'active'
$$;

create or replace function my_org() returns uuid
language sql stable security definer set search_path = public as $$
  select org_id from profiles where id = auth.uid() and status = 'active'
$$;

create or replace function my_artist() returns uuid
language sql stable security definer set search_path = public as $$
  select a.id from artists a join profiles p on p.id = a.user_id
  where p.id = auth.uid() and p.status = 'active'
$$;

create or replace function is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(my_role() = 'admin', false)
$$;

create or replace function can_see_deal(d bigint) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from deals x
    left join print_orders o on o.deal_id = x.id
    where x.id = d and (
         is_admin()
      or (my_role() = 'winery'  and x.winery_id  = my_org())
      or (my_role() = 'gallery' and x.gallery_id = my_org())
      or (my_role() = 'artist'  and x.artist_id  = my_artist())
      or (my_role() = 'curator')
      or (my_role() = 'printer' and o.printer_id = my_org())
    )
  )
$$;

-- פרופיל נוצר אוטומטית לכל משתמש חדש
create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into profiles (id, email, phone) values (new.id, new.email, new.phone)
  on conflict (id) do nothing;
  return new;
end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function handle_new_user();

-- משתמש רגיל לא יכול לשנות לעצמו תפקיד, ארגון או סטטוס
create or replace function guard_profile() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() and auth.uid() is not null and coalesce(current_setting('app.bypass', true),'') <> '1' and
     (new.role is distinct from old.role or new.org_id is distinct from old.org_id
      or new.status is distinct from old.status) then
    raise exception 'רק מנהל המערכת יכול לשנות תפקיד, ארגון או סטטוס';
  end if;
  return new;
end $$;
drop trigger if exists profiles_guard on profiles;
create trigger profiles_guard before update on profiles
  for each row execute function guard_profile();

-- =====================================================================
--  תמחור ומעבר שלבים בעסקה (רק דרך פונקציות, לא עדכון ישיר)
-- =====================================================================
create or replace function deal_price(d deals) returns numeric
language sql stable security definer set search_path = public as $$
  select round(
    round(a.floor_price
      * case d.license_type when 'series' then 2.2 else 1 end
      * case d.qty_tier when 'b' then 1.5 when 'c' then 2 else 1 end
      * case when d.exclusive then 1.6 else 1 end / 50) * 50
    * (1 + d.adj_pct / 100.0) / 50) * 50
  from artists a where a.id = d.artist_id
$$;

create or replace function notify_deal(d bigint, msg text, roles app_role[]) returns void
language plpgsql security definer set search_path = public as $$
declare x deals;
begin
  select * into x from deals where id = d;
  insert into notifications (user_id, deal_id, body)
  select p.id, d, msg from profiles p
  where p.status = 'active' and p.role = any(roles) and (
       (p.role = 'winery'  and p.org_id = x.winery_id)
    or (p.role = 'gallery' and p.org_id = x.gallery_id)
    or (p.role = 'artist'  and p.id = (select user_id from artists where id = x.artist_id))
    or (p.role = 'admin'));
end $$;

-- יקב שולח בקשה
create or replace function request_license(
  p_work bigint, p_wine bigint, p_design text, p_label text,
  p_type text, p_qty text, p_exclusive boolean) returns bigint
language plpgsql security definer set search_path = public as $$
declare w works; a artists; new_id bigint;
begin
  if coalesce(my_role()::text, '') <> 'winery' then raise exception 'רק יקב יכול לשלוח בקשה'; end if;
  select * into w from works where id = p_work and status = 'live' and available;
  if not found then raise exception 'היצירה אינה זמינה'; end if;
  select * into a from artists where id = w.artist_id;
  insert into deals (winery_id, gallery_id, artist_id, work_id, wine_id, design_code,
                     wine_label, license_type, qty_tier, exclusive, created_by)
  values (my_org(), a.gallery_id, a.id, w.id, p_wine, p_design, p_label,
          p_type, p_qty, coalesce(p_exclusive,false), auth.uid())
  returning id into new_id;
  perform notify_deal(new_id, 'בקשת רישיון חדשה', array['gallery','admin']::app_role[]);
  insert into audit_log(action, entity, entity_id) values ('request','deal',new_id::text);
  return new_id;
end $$;

-- כל שאר השלבים
create or replace function advance_deal(p_deal bigint, p_action text,
                                        p_adj int default 0, p_note text default null)
returns deal_status
language plpgsql security definer set search_path = public as $$
declare x deals; r app_role := my_role(); s settings; c numeric;
begin
  select * into x from deals where id = p_deal for update;
  if not found or not can_see_deal(p_deal) then raise exception 'אין גישה לעסקה'; end if;
  select * into s from settings where id = 1;

  if p_action = 'price' and x.status = 'sent' and r in ('gallery','admin') then
    c := s.comm_pct;
    x.adj_pct := greatest(-15, least(15, coalesce(p_adj,0)));
    update deals set adj_pct = x.adj_pct, note = p_note, comm_pct = c,
      price_net = deal_price(x), status = 'priced', updated_at = now() where id = p_deal;
    perform notify_deal(p_deal, 'הגלריה תמחרה. נדרשת הסכמת האמן', array['artist']::app_role[]);

  elsif p_action = 'approve' and x.status = 'priced' and (r = 'admin' or (r = 'artist' and x.artist_id = my_artist())) then
    update deals set status = 'sign', updated_at = now() where id = p_deal;
    insert into contracts (deal_id, terms) values (p_deal, jsonb_build_object(
      'license_type', x.license_type, 'qty_tier', x.qty_tier, 'exclusive', x.exclusive,
      'price_net', x.price_net, 'vat_pct', s.vat_pct,
      'restrict', (select restrict_text from artists where id = x.artist_id)))
    on conflict (deal_id) do nothing;
    perform notify_deal(p_deal, 'החוזה מוכן לחתימה', array['winery']::app_role[]);

  elsif p_action = 'sign' and x.status = 'sign' and r = 'winery' and x.winery_id = my_org() then
    update deals set status = 'pay', signed_at = now(), updated_at = now() where id = p_deal;
    update contracts set signed_by = auth.uid(), signed_at = now() where deal_id = p_deal;
    insert into invoices (deal_id, net, vat, total)
    values (p_deal, x.price_net, round(x.price_net * s.vat_pct / 100, 2),
            round(x.price_net * (1 + s.vat_pct / 100), 2))
    on conflict (deal_id) do nothing;
    perform notify_deal(p_deal, 'החוזה נחתם. ממתין לתשלום', array['gallery']::app_role[]);

  elsif p_action = 'paid' and x.status = 'pay' and r in ('gallery','admin') then
    p_note := nullif(p_note,'');
    update deals set status = 'active', paid_at = current_date,
      ends_at = current_date + interval '1 year', updated_at = now() where id = p_deal;
    update invoices set confirmed_by = auth.uid(), confirmed_at = now(),
      number = coalesce(nullif(p_note,''), number) where deal_id = p_deal;
    perform notify_deal(p_deal, 'הרישיון פעיל', array['winery','artist']::app_role[]);

  elsif p_action = 'change' and x.status = 'priced' and (r = 'admin' or (r = 'artist' and x.artist_id = my_artist())) then
    update deals set status = 'sent', updated_at = now() where id = p_deal;
    perform notify_deal(p_deal, 'האמן ביקש שינוי. הבקשה חזרה לתמחור', array['gallery']::app_role[]);

  elsif p_action = 'reject' and x.status in ('sent','priced')
        and (r in ('gallery','admin') or (r = 'artist' and x.artist_id = my_artist())) then
    update deals set status = 'rejected', note = p_note, updated_at = now() where id = p_deal;
    perform notify_deal(p_deal, 'הבקשה נדחתה', array['winery']::app_role[]);

  elsif p_action = 'order' and x.status = 'active' and (r = 'admin' or (r = 'winery' and x.winery_id = my_org())) then
    insert into print_orders (deal_id, printer_id, due)
    values (p_deal, (select id from organizations where kind = 'printer' and active order by created_at limit 1),
            current_date + 21)
    on conflict (deal_id) do nothing;

  elsif p_action = 'cancel' and x.status in ('sent','priced','sign')
        and (r = 'admin' or (r = 'winery' and x.winery_id = my_org())) then
    update deals set status = 'cancelled', note = p_note, updated_at = now() where id = p_deal;

  else
    raise exception 'הפעולה % אינה אפשרית בשלב הזה', p_action;
  end if;

  insert into audit_log(action, entity, entity_id, data)
  values (p_action, 'deal', p_deal::text, jsonb_build_object('adj', p_adj, 'note', p_note));
  select status into x.status from deals where id = p_deal;
  return x.status;
end $$;

-- =====================================================================
--  הרשאות לפי תפקיד (Row Level Security)
-- =====================================================================
alter table settings      enable row level security;
alter table organizations enable row level security;
alter table profiles      enable row level security;
alter table artists       enable row level security;
alter table works         enable row level security;
alter table wines         enable row level security;
alter table designs       enable row level security;
alter table deals         enable row level security;
alter table deal_messages enable row level security;
alter table contracts     enable row level security;
alter table invoices      enable row level security;
alter table renders       enable row level security;
alter table print_orders  enable row level security;
alter table applications  enable row level security;
alter table notifications enable row level security;
alter table audit_log     enable row level security;

-- מוחקים מדיניות קודמת כדי שאפשר יהיה להריץ שוב
do $$ declare p record; begin
  for p in select policyname, tablename from pg_policies where schemaname = 'public' loop
    execute format('drop policy %I on %I', p.policyname, p.tablename);
  end loop;
end $$;

-- הגדרות: כולם קוראים, רק מנהל משנה
create policy settings_read  on settings for select to authenticated using (true);
create policy settings_admin on settings for update to authenticated using (is_admin());

-- ארגונים: כל משתמש פעיל רואה שמות; מנהל מנהל; גלריה מעדכנת את עצמה
create policy org_read   on organizations for select to authenticated using (my_role() is not null);
create policy org_admin  on organizations for all    to authenticated using (is_admin()) with check (is_admin());
create policy org_self   on organizations for update to authenticated
  using (id = my_org() and my_role() in ('gallery','winery','printer')) with check (id = my_org());

-- משתמשים: כל אחד רואה את עצמו ואת אנשי הארגון שלו; מנהל רואה הכל
create policy prof_self  on profiles for select to authenticated
  using (id = auth.uid() or is_admin()
         or (org_id is not null and org_id = my_org() and coalesce(my_role()::text,'') <> 'customer' and coalesce(role::text,'') <> 'customer'));
create policy prof_upd   on profiles for update to authenticated
  using (id = auth.uid() or is_admin()) with check (id = auth.uid() or is_admin());

-- אמנים: פרופיל ציבורי לכל משתמש פעיל; האמן מעדכן את עצמו; הגלריה מנהלת את האמנים שלה
create policy art_read   on artists for select to authenticated using (my_role() is not null);
create policy art_self   on artists for update to authenticated
  using (id = my_artist()) with check (id = my_artist());
create policy art_gal    on artists for all to authenticated
  using (is_admin() or (my_role() = 'gallery' and gallery_id = my_org()))
  with check (is_admin() or (my_role() = 'gallery' and gallery_id = my_org()));

-- יצירות: יקב רואה רק יצירות שאושרו; אמן, גלריה, אוצר ומנהל רואים לפי תחום
create policy work_read  on works for select to authenticated using (
     (status = 'live' and my_role() is not null)
  or artist_id = my_artist()
  or my_role() in ('curator','admin')
  or (my_role() = 'gallery' and artist_id in (select id from artists where gallery_id = my_org())));
create policy work_ins   on works for insert to authenticated with check (
     artist_id = my_artist() or is_admin()
  or (my_role() = 'gallery' and artist_id in (select id from artists where gallery_id = my_org())));
create policy work_upd   on works for update to authenticated using (
     artist_id = my_artist() or my_role() in ('curator','admin')
  or (my_role() = 'gallery' and artist_id in (select id from artists where gallery_id = my_org())));
create policy work_del   on works for delete to authenticated using (is_admin()
  or (artist_id = my_artist() and status in ('pending','rejected')));

-- אמן לא יכול לאשר לעצמו יצירה. הגלריה מעבירה לבדיקה, האוצרות מפרסמים
create or replace function guard_work() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(my_role()::text,'') not in ('curator','admin') and auth.uid() is not null then
    if tg_op = 'INSERT' then new.status := 'pending'; new.pick_rank := null;
    elsif new.status is distinct from old.status and my_role() = 'gallery'
          and old.status = 'pending' and new.status in ('review','rejected') then
      null;
    elsif new.status is distinct from old.status and new.status in ('live','review','rejected') then
      raise exception 'רק האוצרות מאשרים יצירות';
    elsif new.pick_rank is distinct from old.pick_rank then
      new.pick_rank := old.pick_rank;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists works_guard on works;
create trigger works_guard before insert or update on works
