-- יינות ועיצובים: רק היקב עצמו (ומנהל)
create policy wine_all   on wines for all to authenticated
  using (is_admin() or (my_role() = 'winery' and winery_id = my_org()))
  with check (is_admin() or (my_role() = 'winery' and winery_id = my_org()));
create policy des_all    on designs for all to authenticated
  using (is_admin() or wine_id in (select id from wines where winery_id = my_org() and my_role() = 'winery'))
  with check (is_admin() or wine_id in (select id from wines where winery_id = my_org() and my_role() = 'winery'));
create policy des_read   on designs for select to authenticated
  using (code in (select design_code from deals where can_see_deal(id)));
create policy wine_read  on wines for select to authenticated
  using (id in (select wine_id from deals where can_see_deal(id)));

-- עסקאות: קריאה לפי מעורבות; שינוי רק דרך הפונקציות
create policy deal_read  on deals for select to authenticated using (can_see_deal(id));

-- הודעות: מי שרואה את העסקה קורא וכותב
create policy msg_read   on deal_messages for select to authenticated using (can_see_deal(deal_id));
create policy msg_write  on deal_messages for insert to authenticated
  with check (can_see_deal(deal_id) and sender = auth.uid() and my_role() <> 'printer');

-- חוזים וחשבוניות: לפי העסקה, ללא שינוי ישיר
create policy con_read   on contracts for select to authenticated using (can_see_deal(deal_id) and my_role() <> 'printer');
create policy inv_read   on invoices  for select to authenticated using (can_see_deal(deal_id) and my_role() in ('winery','gallery','admin'));

-- הדמיות: אוצרות ומנהל מאשרים; משתתפים בעסקה רואים
create policy rnd_read   on renders for select to authenticated using (
  my_role() in ('curator','admin') or (deal_id is not null and can_see_deal(deal_id))
  or created_by = auth.uid());
create policy rnd_ins    on renders for insert to authenticated with check (created_by = auth.uid());
create policy rnd_rev    on renders for update to authenticated using (my_role() in ('curator','admin'));

-- הזמנות דפוס: בית הדפוס מעדכן שלב; גלריה ומנהל משייכים
