  is_admin() or (my_role() = 'printer' and printer_id = my_org())
  or (my_role() = 'gallery' and deal_id in (select id from deals where gallery_id = my_org())));

-- בקשות הצטרפות: כל משתמש מחובר שולח; מנהל ואוצר מטפלים
create policy app_ins    on applications for insert to authenticated with check (created_by = auth.uid());
create policy app_read   on applications for select to authenticated using (created_by = auth.uid() or my_role() in ('admin','curator'));
create policy app_upd    on applications for update to authenticated using (my_role() in ('admin','curator'));

