create or replace function org_slug() returns trigger
language plpgsql as $$
begin
  if new.slug is null and new.kind = 'winery' then
    new.slug := 'w' || substr(replace(new.id::text, '-', ''), 1, 8);
  end if;
  return new;
end $$;
drop trigger if exists org_slug_t on organizations;
create trigger org_slug_t before insert or update on organizations
  for each row execute function org_slug();
update organizations set slug = 'w' || substr(replace(id::text, '-', ''), 1, 8)
where kind = 'winery' and slug is null;

create table if not exists customer_orders (
  id            bigint generated by default as identity (start with 5001) primary key,
  winery_id     uuid not null references organizations(id),
  customer_id   uuid not null default auth.uid() references profiles(id),
  cust          jsonb not null,           -- שם, טלפון, מייל, הערה
  design        jsonb not null,           -- העיצוב של הלקוח
  winery_design jsonb,                    -- העיצוב אחרי התאמות היקב
  winery_note   text,
  total         numeric,
  status        text not null default 'sent' check (status in ('sent','review','approved','print','done','cancel')),
  log           jsonb not null default '[]',
  created_at    timestamptz not null default now()
);
alter table customer_orders enable row level security;
alter table customer_orders add column if not exists paid_at timestamptz;
