     customer_id = auth.uid() or is_admin()
  or (my_role()::text = 'winery'  and winery_id = my_org())
  or (my_role()::text = 'printer' and status in ('print','done')));
create policy co_ins on customer_orders for insert to authenticated with check (
  customer_id = auth.uid() and my_role()::text = 'customer' and winery_id = my_org() and status = 'sent'
  and winery_design is null);

