--  שימוש במנוע הצילום: נרשם ונבדק בשרת, לא בדפדפן
-- =====================================================================
alter table settings add column if not exists text_daily_quota int not null default 60;
alter table settings add column if not exists engine_daily_cap int not null default 200;
alter table settings add column if not exists engine_per_minute int not null default 6;

create table if not exists engine_usage (
  id         bigint generated by default as identity primary key,
  user_id    uuid not null default auth.uid() references profiles(id) on delete cascade,
  kind       text not null check (kind in ('image','text')),
  created_at timestamptz not null default now()
);
create index if not exists engine_usage_user_idx on engine_usage(user_id, created_at);
create index if not exists engine_usage_day_idx  on engine_usage(created_at);
