-- ---------- יומן: נכתב רק מהשרת ----------
drop policy if exists log_ins on audit_log;
create or replace function audit_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare o jsonb := case when tg_op = 'INSERT' then '{}'::jsonb else to_jsonb(old) end;
        n jsonb := case when tg_op = 'DELETE' then '{}'::jsonb else to_jsonb(new) end;
        d jsonb := '{}'::jsonb; k text; id text;
begin
  for k in select jsonb_object_keys(o || n) loop
    if k in ('version','updated_at','created_at','log','pop_score','excl_lock') then continue; end if;
    if (o -> k) is distinct from (n -> k) then
      d := d || jsonb_build_object(k, jsonb_build_array(o -> k, n -> k));
    end if;
  end loop;
  if d = '{}'::jsonb then return coalesce(new, old); end if;
  id := coalesce(n ->> 'id', o ->> 'id');
  insert into audit_log (actor, action, entity, entity_id, data)
  values (auth.uid(), lower(tg_op) || ':' || tg_table_name, tg_table_name, id, d);
  return coalesce(new, old);
end $$;
do $$ declare t text; begin
  foreach t in array array['works','organizations','profiles','settings','artists','wines'] loop
    execute format('drop trigger if exists audit_%1$s on %1$s', t);
    execute format('create trigger audit_%1$s after insert or update or delete on %1$s for each row execute function audit_row()', t);
  end loop;
end $$;

-- ---------- מחיר הזמנת לקוח: נקבע בשרת ----------
create or replace function corder_price(p_winery uuid, d jsonb) returns numeric
language plpgsql stable security definer set search_path = public as $$
begin return corder_price_of(coalesce((select pricing from organizations where id = p_winery), '{}'), d); end $$;
-- הנוסחה עצמה, בלי גישה לטבלאות. זהה ל-domain/pricing.ts ולמחירון בדפדפן
create or replace function corder_price_of(pr jsonb, d jsonb) returns numeric
language plpgsql immutable as $$
declare base numeric; art numeric; shp numeric; unit numeric; q int; disc numeric;
begin
  pr := coalesce(pr, '{}');
  base := coalesce((pr -> 'prices' ->> (d ->> 'wine'))::numeric, 100);
  art  := coalesce((pr -> 'artist' ->> (d ->> 'artist'))::numeric, 0);
  shp  := coalesce((coalesce(pr -> 'shape', '{"rect":0,"oval":2,"arch":3}') ->> (d ->> 'shape'))::numeric, 0);
  unit := base + art + shp
        + case when (d ->> 'foil')::boolean then coalesce((pr ->> 'foil')::numeric, 6) else 0 end
        + case when (d ->> 'emboss')::boolean then coalesce((pr ->> 'emboss')::numeric, 4) else 0 end;
  q := greatest(1, coalesce((d ->> 'qty')::int, 1));
  disc := case
    when q >= coalesce((pr ->> 't2')::int, 60) then coalesce((pr ->> 'd2')::numeric, 15)
    when q >= coalesce((pr ->> 't1')::int, 24) then coalesce((pr ->> 'd1')::numeric, 10)
    when q >= 6 then coalesce((pr ->> 'caseDisc')::numeric, 5)
    else 0 end;
  return round(unit * (1 - disc / 100)) * q;
end $$;

-- בדיקת העיצוב שהלקוח או היקב שולחים
create or replace function corder_check(p_winery uuid, d jsonb) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if d is null or jsonb_typeof(d) <> 'object' then raise exception 'העיצוב חסר'; end if;
  if not exists (select 1 from wines where id = (d ->> 'wine')::bigint and winery_id = p_winery) then
    raise exception 'היין לא שייך ליקב'; end if;
  if not exists (select 1 from works where id = (d ->> 'work')::bigint and status = 'live') then
    raise exception 'היצירה אינה זמינה'; end if;
  if coalesce((d ->> 'qty')::int, 0) not between 1 and 10000 then raise exception 'כמות לא תקינה'; end if;
  if length(coalesce(d ->> 'name', '')) > 24 then raise exception 'השם על התווית ארוך מדי'; end if;
  if length(coalesce(d ->> 'ded', '')) > 40 then raise exception 'ההקדשה ארוכה מדי'; end if;
  if coalesce(d ->> 'shape', 'rect') not in ('rect','oval','arch') then raise exception 'צורת תווית לא מוכרת'; end if;
  if coalesce((d ->> 'pos')::int, 50) not between 0 and 100 or coalesce((d ->> 'zoom')::int, 100) not between 100 and 200 then
    raise exception 'מיקום לא תקין'; end if;
end $$;

create or replace function corder_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if length(coalesce(new.cust ->> 'n', '')) not between 1 and 80
     or length(coalesce(new.cust ->> 'ph', '')) > 30
     or length(coalesce(new.cust ->> 'em', '')) > 120
     or length(coalesce(new.cust ->> 'note', '')) > 500 then
    if tg_op = 'INSERT' then raise exception 'פרטי הקשר אינם תקינים'; end if;
  end if;
  perform corder_check(new.winery_id, new.design);
  if new.winery_design is not null then perform corder_check(new.winery_id, new.winery_design); end if;
  new.total := corder_price(new.winery_id, coalesce(new.winery_design, new.design));
  return new;
end $$;
drop trigger if exists corder_guard_t on customer_orders;
create trigger corder_guard_t before insert or update of design, winery_design, cust on customer_orders
  for each row execute function corder_guard();

-- ---------- טבלת מעברים לעסקה ----------
create table if not exists deal_transitions (
  from_status deal_status not null,
  action      text not null,
  to_status   deal_status not null,
  roles       text[] not null,     -- מי מורשה. 'artist:own' = האמן של העסקה וכו'
  primary key (from_status, action)
);
alter table deal_transitions enable row level security;
drop policy if exists dt_read on deal_transitions;
create policy dt_read on deal_transitions for select to authenticated using (true);
insert into deal_transitions values
  ('sent',   'price',   'priced',    '{gallery:own,admin}'),
  ('priced', 'approve', 'sign',      '{artist:own,admin}'),
  ('priced', 'change',  'sent',      '{artist:own,admin}'),
  ('sent',   'reject',  'rejected',  '{gallery:own,artist:own,admin}'),
  ('priced', 'reject',  'rejected',  '{gallery:own,artist:own,admin}'),
  ('sign',   'sign',    'pay',       '{winery:own}'),
  ('pay',    'paid',    'active',    '{gallery:own,admin}'),
  ('active', 'order',   'active',    '{winery:own,admin}'),
  ('sent',   'cancel',  'cancelled', '{winery:own,admin}'),
  ('priced', 'cancel',  'cancelled', '{winery:own,admin}'),
  ('sign',   'cancel',  'cancelled', '{winery:own,admin}')
on conflict (from_status, action) do update set to_status = excluded.to_status, roles = excluded.roles;

create or replace function deal_allowed(x deals, p_action text) returns deal_status
language plpgsql stable security definer set search_path = public as $$
declare t deal_transitions; r text := my_role()::text; ok boolean := false; who text;
begin
  select * into t from deal_transitions where from_status = x.status and action = p_action;
  if not found then return null; end if;
  foreach who in array t.roles loop
    ok := ok or (who = 'admin' and r = 'admin')
              or (who = 'gallery:own' and r = 'gallery' and x.gallery_id = my_org())
              or (who = 'winery:own'  and r = 'winery'  and x.winery_id  = my_org())
              or (who = 'artist:own'  and x.artist_id = my_artist() and r in ('artist','admin'));
  end loop;
  return case when ok then t.to_status end;
end $$;

-- ---------- תבניות חוזה ----------
create table if not exists contract_templates (
  version    int primary key,
  body       text not null,
  active     boolean not null default false,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);
alter table contract_templates enable row level security;
drop policy if exists ct_read on contract_templates;
drop policy if exists ct_admin on contract_templates;
create policy ct_read  on contract_templates for select to authenticated using (my_role() is not null);
create policy ct_admin on contract_templates for all to authenticated using (is_admin()) with check (is_admin());
insert into contract_templates (version, active, body) values (1, true,
'1. הצדדים
{gallery}, בשם האמן {artist} ("הגלריה"), ו־{winery} ("היקב").

2. היצירה והשימוש
היצירה "{work}" על תווית היין "{wine}", על הקרטון ובשיווק הבקבוק בלבד. שימוש נוסף, כמו מוצרי משנה, דורש רישיון נפרד.

3. תקופה וכמות
{type}, {qty} בקבוקים, בישראל{exclusive}. בסוף הרישיון יש שישה חודשים למכירת מלאי שכבר הודפס.

4. זכויות
זכות היוצרים נשארת בידי האמן. שם האמן מופיע על התווית. חיתוך או שינוי צבע מעבר לאזורים שהאמן סימן מחייבים את אישורו.{restrict}

5. תמורה
{price} לפני מע״מ. התשלום לפי חשבונית הגלריה. הקבצים נמסרים אחרי שהתשלום מאושר.

6. ביטול ומחלוקות
ביטול לפני חתימה ללא עלות. קבצים פגומים שלא תוקנו מזכים בביטול ובהחזר. מחלוקת נפתרת בגישור, ולאחר מכן לפי הדין בישראל.')
on conflict (version) do nothing;

-- ---------- מזהים חד־פעמיים ----------
create table if not exists idem_keys (
  key        uuid primary key,
  user_id    uuid not null default auth.uid(),
  result     text,
  created_at timestamptz not null default now()
);
alter table idem_keys enable row level security;   -- רק הפונקציות ניגשות אליה

-- ---------- בקשת רישיון (עם מזהה חד־פעמי) ----------
drop function if exists request_license(bigint,bigint,text,text,text,text,boolean);
create or replace function request_license(
  p_work bigint, p_wine bigint, p_design text, p_label text,
  p_type text, p_qty text, p_exclusive boolean, p_key uuid default null) returns bigint
language plpgsql security definer set search_path = public as $$
declare w works; a artists; new_id bigint; prev text;
begin
  if coalesce(my_role()::text, '') <> 'winery' then raise exception 'רק יקב יכול לשלוח בקשה'; end if;
  if p_key is not null then
    select result into prev from idem_keys where key = p_key and user_id = auth.uid();
    if found then return prev::bigint; end if;
  end if;
  if p_type not in ('one','series') or p_qty not in ('a','b','c') then raise exception 'סוג רישיון לא תקין'; end if;
  select * into w from works where id = p_work and status = 'live' and available;
  if not found then raise exception 'היצירה אינה זמינה'; end if;
  if p_wine is not null and not exists (select 1 from wines where id = p_wine and winery_id = my_org()) then
    raise exception 'היין לא שייך ליקב'; end if;
  select * into a from artists where id = w.artist_id;
  insert into deals (winery_id, gallery_id, artist_id, work_id, wine_id, design_code,
                     wine_label, license_type, qty_tier, exclusive, created_by)
  values (my_org(), a.gallery_id, a.id, w.id, p_wine, p_design, left(p_label, 80),
          p_type, p_qty, coalesce(p_exclusive,false), auth.uid())
  returning id into new_id;
  if p_key is not null then insert into idem_keys (key, result) values (p_key, new_id::text); end if;
  perform notify_deal(new_id, 'בקשת רישיון חדשה', array['gallery','admin']::app_role[]);
  insert into audit_log(actor, action, entity, entity_id) values (auth.uid(), 'request','deal',new_id::text);
  return new_id;
end $$;
grant execute on function request_license(bigint,bigint,text,text,text,text,boolean,uuid) to authenticated;

-- ---------- חוזה: נוצר מהתבנית הפעילה, עם תמונת מצב וטביעת אצבע ----------
create or replace function deal_make_contract(p_deal bigint) returns void
language plpgsql security definer set search_path = public as $$
declare x deals; s settings; t contract_templates; terms jsonb;
begin
  select * into x from deals where id = p_deal;
  select * into s from settings where id = 1;
  select * into t from contract_templates where active order by version desc limit 1;
  terms := jsonb_build_object(
    'license_type', x.license_type, 'qty_tier', x.qty_tier, 'exclusive', x.exclusive,
    'price_net', x.price_net, 'vat_pct', s.vat_pct, 'comm_pct', x.comm_pct,
    'restrict', (select restrict_text from artists where id = x.artist_id),
    'restrict_tags', (select restrict_tags from artists where id = x.artist_id),
    'design', (select to_jsonb(d) - 'created_by' from designs d where d.code = x.design_code),
    'work', (select jsonb_build_object('id', id, 'title', title, 'image', image_path) from works where id = x.work_id),
    'template', t.body);
  insert into contracts (deal_id, terms, template_version, terms_hash)
  values (p_deal, terms, t.version, md5(terms::text))
  on conflict (deal_id) do nothing;
end $$;

-- ---------- מעבר שלב בעסקה: לפי הטבלה, עם בדיקת גרסה ----------
drop function if exists advance_deal(bigint,text,int,text);
create or replace function advance_deal(p_deal bigint, p_action text,
  p_adj int default 0, p_note text default null, p_version int default null)
returns deal_status
language plpgsql security definer set search_path = public as $$
declare x deals; s settings; nxt deal_status; ar artists;
begin
  select * into x from deals where id = p_deal for update;
  if not found or not can_see_deal(p_deal) then raise exception 'אין גישה לעסקה'; end if;
  if p_version is not null and p_version <> x.version then
    raise exception 'העסקה עודכנה בינתיים. הנה המצב החדש'; end if;
  nxt := deal_allowed(x, p_action);
  if nxt is null then raise exception 'הפעולה % אינה אפשרית בשלב הזה', p_action; end if;
  select * into s from settings where id = 1;
  p_note := nullif(left(coalesce(p_note,''), 500), '');

  if p_action = 'price' then
    x.adj_pct := greatest(-15, least(15, coalesce(p_adj,0)));
    update deals set adj_pct = x.adj_pct, note = p_note, comm_pct = s.comm_pct,
      price_net = deal_price(x), status = nxt, updated_at = now() where id = p_deal;
    select * into ar from artists where id = x.artist_id;
    -- הסכמה מראש: בציר אחד, עד 3,000 בקבוקים, בלי בלעדיות ובלי שינוי מחיר
    if ar.pre_consent and x.license_type = 'one' and x.qty_tier = 'a' and not x.exclusive and x.adj_pct = 0 then
      update deals set status = 'sign', updated_at = now() where id = p_deal;
      perform deal_make_contract(p_deal);
      perform notify_deal(p_deal, 'האמן הסכים מראש. החוזה מוכן לחתימה', array['winery','artist']::app_role[]);
    else
      perform notify_deal(p_deal, 'הגלריה תמחרה. נדרשת הסכמת האמן', array['artist']::app_role[]);
    end if;
  elsif p_action = 'approve' then
    update deals set status = nxt, updated_at = now() where id = p_deal;
    perform deal_make_contract(p_deal);
    perform notify_deal(p_deal, 'החוזה מוכן לחתימה', array['winery']::app_role[]);
  elsif p_action = 'sign' then
    update deals set status = nxt, signed_at = now(), updated_at = now() where id = p_deal;
    update contracts set signed_by = auth.uid(), signed_at = now() where deal_id = p_deal;
    insert into invoices (deal_id, net, vat, total)
    values (p_deal, x.price_net, round(x.price_net * s.vat_pct / 100, 2), round(x.price_net * (1 + s.vat_pct / 100), 2))
    on conflict (deal_id) do nothing;
    perform notify_deal(p_deal, 'החוזה נחתם. ממתין לתשלום', array['gallery']::app_role[]);
  elsif p_action = 'paid' then
    update deals set status = nxt, paid_at = current_date, ends_at = current_date + interval '1 year', updated_at = now() where id = p_deal;
    update invoices set confirmed_by = auth.uid(), confirmed_at = now(), number = coalesce(p_note, number) where deal_id = p_deal;
    perform notify_deal(p_deal, 'הרישיון פעיל', array['winery','artist']::app_role[]);
  elsif p_action = 'change' then
    update deals set status = nxt, updated_at = now() where id = p_deal;
    perform notify_deal(p_deal, 'האמן ביקש שינוי. הבקשה חזרה לתמחור', array['gallery']::app_role[]);
  elsif p_action = 'reject' then
    update deals set status = nxt, note = p_note, updated_at = now() where id = p_deal;
    perform notify_deal(p_deal, 'הבקשה נדחתה', array['winery']::app_role[]);
  elsif p_action = 'order' then
    insert into print_orders (deal_id, printer_id, due)
    values (p_deal, (select id from organizations where kind = 'printer' and active order by created_at limit 1), current_date + 21)
    on conflict (deal_id) do nothing;
  elsif p_action = 'cancel' then
    update deals set status = nxt, note = p_note, updated_at = now() where id = p_deal;
  end if;

  insert into audit_log(actor, action, entity, entity_id, data)
  values (auth.uid(), p_action, 'deal', p_deal::text, jsonb_build_object('adj', p_adj, 'note', p_note));
  select status into nxt from deals where id = p_deal;
  return nxt;
end $$;
grant execute on function advance_deal(bigint,text,int,text,int) to authenticated;

-- ---------- פעולות על הזמנת לקוח: עם בדיקת גרסה ----------
do $$ declare f text;
begin
  for f in select oid::regprocedure::text from pg_proc where proname = 'corder_action' and pronamespace = 'public'::regnamespace loop
    execute 'drop function ' || f;
  end loop;
end $$;
create or replace function corder_action(p_id bigint, p_action text, p_design jsonb default null,
                                         p_note text default null, p_total numeric default null,
                                         p_version int default null)
returns text
language plpgsql security definer set search_path = public as $$
declare o customer_orders; r text := my_role()::text; win boolean; cus boolean; msg text;
begin
  select * into o from customer_orders where id = p_id for update;
  if not found then raise exception 'ההזמנה לא נמצאה'; end if;
  if p_version is not null and p_version <> o.version then raise exception 'ההזמנה עודכנה בינתיים. הנה המצב החדש'; end if;
  win := r = 'admin' or (r = 'winery' and o.winery_id = my_org());
  cus := o.customer_id = auth.uid();
  p_note := nullif(left(coalesce(p_note,''), 500), '');

  if p_action = 'wsave' and win and o.status = 'sent' then
    update customer_orders set winery_design = p_design where id = p_id;   -- המחיר מחושב בטריגר
    return o.status;
  elsif p_action = 'wundo' and win and o.status = 'sent' then
    update customer_orders set winery_design = null where id = p_id; msg := 'היקב ביטל את ההתאמות';
  elsif p_action = 'wsend' and win and o.status = 'sent' and o.winery_design is not null then
    update customer_orders set status = 'review', winery_note = p_note where id = p_id;
    msg := 'היקב הציע התאמות לאישורך'; perform notify_users(null, null, o.customer_id, msg);
  elsif p_action = 'wok' and win and o.status = 'sent' then
    -- היינן מאשר מצידו; התווית עוברת לאישור האמן או הגלריה
    update customer_orders set status = 'label', winery_design = null, label_ok_w = o.label_round where id = p_id;
    insert into label_notes (entity, entity_id, round, side, kind) values ('corder', p_id, o.label_round, 'winery', 'approve');
    msg := 'היקב אישר את העיצוב. התווית עברה לאישור האמן'; perform notify_users(null, null, o.customer_id, msg);
    perform label_notify('corder', p_id, 'תווית של לקוח מחכה לאישור שלך', array['art']);
  elsif p_action = 'cok' and cus and o.status = 'review' then
    update customer_orders set status = 'label', label_ok_w = o.label_round where id = p_id;
    insert into label_notes (entity, entity_id, round, side, kind) values ('corder', p_id, o.label_round, 'winery', 'approve');
    msg := 'הלקוח אישר את ההתאמות. התווית עברה לאישור האמן'; perform notify_users(o.winery_id, 'winery', null, msg);
    perform label_notify('corder', p_id, 'תווית של לקוח מחכה לאישור שלך', array['art']);
  elsif p_action = 'cchange' and cus and o.status = 'review' then
    update customer_orders set status = 'sent' where id = p_id;
    msg := 'הלקוח ביקש שינוי: ' || coalesce(p_note, ''); perform notify_users(o.winery_id, 'winery', null, msg);
  elsif p_action = 'wpaid' and win and o.status = 'approved' and o.paid_at is null then
    update customer_orders set paid_at = now() where id = p_id; msg := 'היקב סימן שהתשלום התקבל';
  elsif p_action = 'wprint' and win and o.status = 'approved' and o.paid_at is not null then
    update customer_orders set status = 'print' where id = p_id;
    msg := 'ההזמנה עברה לדפוס'; perform notify_users(null, null, o.customer_id, msg);
  elsif p_action = 'done' and (win or r = 'printer') and o.status = 'print' then
    update customer_orders set status = 'done' where id = p_id;
    msg := 'הבקבוקים מוכנים'; perform notify_users(null, null, o.customer_id, msg);
  elsif p_action = 'cancel' and (win or cus) and o.status in ('sent','review') then
    update customer_orders set status = 'cancel' where id = p_id; msg := 'ההזמנה בוטלה';
  else
    raise exception 'הפעולה אינה אפשרית בשלב הזה';
  end if;
  update customer_orders set log = log || jsonb_build_array(jsonb_build_object('t', msg, 'at', now())) where id = p_id;
  select status into o.status from customer_orders where id = p_id;
  return o.status;
end $$;
grant execute on function corder_action(bigint,text,jsonb,text,numeric,int) to authenticated;

-- ---------- אחסון: מקור פרטי, תצוגות מקדימות ציבוריות ----------
insert into storage.buckets (id, name, public) values ('previews','previews',true)
on conflict (id) do update set public = true;
drop policy if exists "works read"     on storage.objects;
drop policy if exists "previews write" on storage.objects;
-- קובץ המקור: רק מי שצריך אותו לעבודה או לדפוס
create policy "works read" on storage.objects for select to authenticated using (
  bucket_id = 'works' and (
       is_admin() or my_role()::text = 'curator'
    or (storage.foldername(name))[1] = auth.uid()::text
    or exists (select 1 from works w join artists a on a.id = w.artist_id
               where w.image_path = name and (a.gallery_id = my_org() or a.user_id = auth.uid()))
    or exists (select 1 from works w join deals d on d.work_id = w.id
               where w.image_path = name and d.status = 'active' and can_see_deal(d.id))
    or exists (select 1 from works w join customer_orders co
                 on (co.design ->> 'work')::bigint = w.id or (co.winery_design ->> 'work')::bigint = w.id
               where w.image_path = name and co.status in ('approved','print','done')
                 and (co.winery_id = my_org() or my_role()::text = 'printer'))));
-- תצוגות מקדימות עם סימן מים: כל אחד מעלה רק לתיקייה שלו
create policy "previews write" on storage.objects for insert to authenticated
  with check (bucket_id = 'previews' and (storage.foldername(name))[1] = auth.uid()::text);

-- ---------- קישורי הצטרפות לארגון ----------
create table if not exists org_invites (
  token      text primary key default replace(gen_random_uuid()::text, '-', ''),
  org_id     uuid not null references organizations(id) on delete cascade,
  role       app_role not null,
  expires_at timestamptz not null default now() + interval '14 days',
  revoked    boolean not null default false,
  uses       int not null default 0,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);
alter table org_invites alter column token set default replace(gen_random_uuid()::text, '-', '');
alter table org_invites enable row level security;
drop policy if exists inv_admin on org_invites;
create policy inv_admin on org_invites for all to authenticated using (is_admin()) with check (is_admin());

create or replace function join_org(p_token text) returns boolean
language plpgsql security definer set search_path = public as $$
declare i org_invites;
begin
  select * into i from org_invites where token = p_token and not revoked and expires_at > now();
  if not found then return false; end if;
  perform set_config('app.bypass', '1', true);
  update profiles set role = i.role, status = 'active', org_id = i.org_id
  where id = auth.uid() and role is null and status = 'pending';
  if not found then return false; end if;
  update org_invites set uses = uses + 1 where token = p_token;
  if i.role::text = 'artist' and not exists (select 1 from artists where user_id = auth.uid()) then
    insert into artists (user_id, gallery_id, name)
    values (auth.uid(), i.org_id, coalesce((select full_name from profiles where id = auth.uid()), 'אמן'));
    perform set_config('app.bypass', '1', true);
    update profiles set org_id = null where id = auth.uid();
  end if;
  return true;
end $$;
grant execute on function join_org(text) to authenticated;

-- ---------- מחיקת חשבון (לקוח, או משתמש שעוד לא שויך) ----------
create or replace function delete_my_account() returns void
language plpgsql security definer set search_path = public, auth as $$
declare r text := coalesce((select role::text from profiles where id = auth.uid()), '');
begin
  if r not in ('', 'customer') then raise exception 'רק מנהל המערכת יכול להסיר חשבון של ארגון'; end if;
  update customer_orders set cust = jsonb_build_object('n', 'לקוח שמחק את חשבונו'), customer_id = null
  where customer_id = auth.uid();
  delete from notifications where user_id = auth.uid();
  delete from auth.users where id = auth.uid();
end $$;
grant execute on function delete_my_account() to authenticated;

-- ---------- הגדרות האמן: הסכמה מראש נשמרת רק על ידי האמן או המנהל ----------
-- (נכלל במדיניות art_self הקיימת)

-- =====================================================================
--  שלב 4 · לקראת עלייה לאוויר
--  עלות ותקציב למנוע, מפסק בטיחות, תור עבודות, הגבלות קבצים,
--  הצטרפות עצמית, מדידת שימוש בלי פרטים אישיים, בדיקת תקינות
-- =====================================================================

-- ---------- מנוע: עלות, תקציב חודשי ומכסה לפי ארגון ----------
alter table settings add column if not exists cost_image numeric not null default 0.5;     -- ₪ לצילום, הערכה
alter table settings add column if not exists cost_text  numeric not null default 0.02;    -- ₪ לניתוח
alter table settings add column if not exists engine_budget numeric not null default 300;  -- ₪ לחודש, לכל המערכת
alter table settings add column if not exists customer_render_quota int not null default 3;
alter table settings add column if not exists breaker_fails int not null default 6;        -- כשלים ב-10 דקות שמשביתים את המנוע
alter table organizations add column if not exists render_quota int;                       -- ריק = לפי ההגדרה הכללית
alter table engine_usage add column if not exists org_id uuid;
alter table engine_usage add column if not exists cost numeric not null default 0;
alter table engine_usage add column if not exists state text not null default 'pending';
do $$ begin
  alter table engine_usage add constraint engine_usage_state check (state in ('pending','ok','failed'));
exception when duplicate_object then null; end $$;
create index if not exists engine_usage_org_idx on engine_usage (org_id, kind, created_at);
create index if not exists engine_usage_time_idx on engine_usage (created_at);
-- שימוש ישן שלא דווח עליו נחשב כמוצלח
update engine_usage set state = 'ok' where state = 'pending' and created_at < now() - interval '10 minutes';

create or replace function engine_spend_month() returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(sum(cost), 0) from engine_usage where state <> 'failed' and created_at >= date_trunc('month', now())
$$;

-- מפסק בטיחות: הרבה כשלים ברצף משביתים את המנוע ל-10 דקות
create or replace function engine_breaker_open() returns boolean
language sql stable security definer set search_path = public as $$
  select count(*) filter (where state = 'failed') >= (select breaker_fails from settings where id = 1)
     and count(*) filter (where state = 'failed') > count(*) filter (where state = 'ok')
  from engine_usage where created_at > now() - interval '10 minutes'
$$;

create or replace function engine_quota_of() returns int
language sql stable security definer set search_path = public as $$
  select case when my_role()::text = 'customer' then (select customer_render_quota from settings where id = 1)
              else coalesce((select render_quota from organizations where id = my_org()), (select render_quota from settings where id = 1)) end
$$;

create or replace function engine_used_month() returns int
language sql stable security definer set search_path = public as $$
  select count(*)::int from engine_usage
  where kind = 'image' and state <> 'failed' and created_at >= date_trunc('month', now())
    and case when my_role()::text = 'customer' or my_org() is null then user_id = auth.uid() else org_id = my_org() end
$$;

create or replace function engine_take(p_kind text) returns int
language plpgsql security definer set search_path = public as $$
declare s settings; used int; minute int; day_all int; lim int; c numeric; o uuid := my_org();
begin
  if my_role() is null then raise exception 'החשבון עוד לא אושר'; end if;
  if p_kind not in ('image','text') then raise exception 'סוג שימוש לא מוכר'; end if;
  select * into s from settings where id = 1;
  if engine_breaker_open() then raise exception 'המנוע מושבת לכמה דקות בגלל תקלה אצל הספק. כדאי לנסות שוב בעוד רבע שעה'; end if;
  perform pg_advisory_xact_lock(hashtext('engine:' || coalesce(o::text, auth.uid()::text)));

  select count(*) into minute from engine_usage where user_id = auth.uid() and created_at > now() - interval '1 minute';
  if minute >= s.engine_per_minute then raise exception 'יותר מדי בקשות בדקה. כדאי לחכות רגע'; end if;

  c := case p_kind when 'image' then s.cost_image else s.cost_text end;
  if engine_spend_month() + c > s.engine_budget and not is_admin() then
    raise exception 'תקציב המנוע לחודש הזה נוצל. מנהל המערכת יכול להגדיל אותו'; end if;

  if p_kind = 'image' then
    used := engine_used_month(); lim := engine_quota_of();
    if used >= lim and not is_admin() then raise exception 'מכסת הצילומים לחודש הזה נגמרה. מנהל המערכת יכול להגדיל אותה'; end if;
    select count(*) into day_all from engine_usage where kind = 'image' and state <> 'failed' and created_at >= date_trunc('day', now());
    if day_all >= s.engine_daily_cap then raise exception 'המנוע הגיע לתקרה היומית של המערכת. כדאי לנסות מחר'; end if;
  else
    select count(*) into used from engine_usage where user_id = auth.uid() and kind = 'text' and state <> 'failed'
      and created_at >= date_trunc('day', now());
    lim := s.text_daily_quota;
    if used >= lim and not is_admin() then raise exception 'מכסת הניתוחים להיום נגמרה'; end if;
  end if;

  insert into engine_usage (user_id, kind, org_id, cost) values (auth.uid(), p_kind, case when my_role()::text = 'customer' then null else o end, c);
  return greatest(0, lim - used - 1);
end $$;
revoke execute on function engine_take(text) from public, anon;
grant execute on function engine_take(text) to authenticated;

-- אחרי התשובה מהספק: הצלחה נספרת, כישלון לא נספר ונכנס למפסק
create or replace function engine_report(p_ok boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  update engine_usage set state = case when p_ok then 'ok' else 'failed' end,
                          cost = case when p_ok then cost else 0 end
  where id = (select id from engine_usage where user_id = auth.uid() and state = 'pending' order by created_at desc limit 1);
end $$;
revoke execute on function engine_report(boolean) from public, anon;
grant execute on function engine_report(boolean) to authenticated;

create or replace function render_quota_left() returns int
language sql stable security definer set search_path = public as $$
  select greatest(0, engine_quota_of() - engine_used_month())
$$;

-- סיכום למנהל: הוצאה החודש, תקציב, מצב המפסק
create or replace function engine_status() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s settings;
begin
  if not is_admin() then raise exception 'רק מנהל המערכת'; end if;
  select * into s from settings where id = 1;
  return jsonb_build_object(
    'spend', engine_spend_month(), 'budget', s.engine_budget, 'breaker', engine_breaker_open(),
    'images', (select count(*) from engine_usage where kind = 'image' and state = 'ok' and created_at >= date_trunc('month', now())),
    'texts',  (select count(*) from engine_usage where kind = 'text'  and state = 'ok' and created_at >= date_trunc('month', now())),
    'failed', (select count(*) from engine_usage where state = 'failed' and created_at > now() - interval '24 hours'),
    'by_org', (select coalesce(jsonb_object_agg(coalesce(o.name, 'לקוחות'), n), '{}') from
               (select org_id, count(*) n from engine_usage where kind = 'image' and state <> 'failed'
                and created_at >= date_trunc('month', now()) group by org_id) u left join organizations o on o.id = u.org_id));
end $$;
grant execute on function engine_status() to authenticated;

-- ---------- תור עבודות: לקיחה בטוחה במקביל, ניסיונות חוזרים, רשימת כשלים ----------
create table if not exists jobs (
  id          bigint generated by default as identity primary key,
  kind        text not null,
  payload     jsonb not null default '{}',
  state       text not null default 'queued' check (state in ('queued','running','done','dead')),
  attempts    int not null default 0,
  max_attempts int not null default 3,
  run_after   timestamptz not null default now(),
  locked_until timestamptz,
  last_error  text,
  result      jsonb,
  created_by  uuid default auth.uid(),
  created_at  timestamptz not null default now(),
  done_at     timestamptz
);
create index if not exists jobs_ready_idx on jobs (state, run_after);
alter table jobs enable row level security;
drop policy if exists jobs_read on jobs;
create policy jobs_read on jobs for select to authenticated using (created_by = auth.uid() or is_admin());

create or replace function job_enqueue(p_kind text, p_payload jsonb) returns bigint
language plpgsql security definer set search_path = public as $$
declare i bigint;
begin
  if my_role() is null then raise exception 'החשבון עוד לא אושר'; end if;
  if p_kind not in ('render','analyze','print_pdf','preview') then raise exception 'סוג עבודה לא מוכר'; end if;
  insert into jobs (kind, payload) values (p_kind, coalesce(p_payload, '{}')) returning id into i;
  return i;
end $$;
grant execute on function job_enqueue(text, jsonb) to authenticated;

-- המעבד לוקח עבודה אחת. עבודה שנתקעה חוזרת לתור אחרי שהזמן שלה עבר
create or replace function job_claim(p_kinds text[], p_seconds int default 120) returns jobs
language plpgsql security definer set search_path = public as $$
declare j jobs;
begin
  select * into j from jobs
  where kind = any(p_kinds) and run_after <= now()
    and (state = 'queued' or (state = 'running' and locked_until < now()))
  order by run_after, id for update skip locked limit 1;
  if not found then return null; end if;
  update jobs set state = 'running', attempts = attempts + 1, locked_until = now() + make_interval(secs => p_seconds)
  where id = j.id returning * into j;
  return j;
end $$;

create or replace function job_finish(p_id bigint, p_ok boolean, p_result jsonb default null, p_error text default null) returns text
language plpgsql security definer set search_path = public as $$
declare j jobs;
begin
  select * into j from jobs where id = p_id for update;
  if not found or j.state <> 'running' then return null; end if;
  if p_ok then
    update jobs set state = 'done', result = p_result, done_at = now(), locked_until = null where id = p_id; return 'done';
  elsif j.attempts >= j.max_attempts then
    update jobs set state = 'dead', last_error = left(p_error, 500), locked_until = null where id = p_id; return 'dead';
  else
    update jobs set state = 'queued', last_error = left(p_error, 500), locked_until = null,
      run_after = now() + make_interval(secs => 30 * power(2, j.attempts - 1)::int) where id = p_id;   -- 30, 60, 120 שניות
    return 'queued';
  end if;
end $$;
-- הלקיחה והסיום רק למעבד בשרת (service role), לא לדפדפן
revoke execute on function job_claim(text[], int) from public, anon, authenticated;
revoke execute on function job_finish(bigint, boolean, jsonb, text) from public, anon, authenticated;

-- ---------- הגבלות קבצים באחסון ----------
do $$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'storage' and table_name = 'buckets' and column_name = 'file_size_limit') then
    update storage.buckets set file_size_limit = 40 * 1024 * 1024, allowed_mime_types = array['image/jpeg','image/png','image/webp','image/tiff'] where id = 'works';
    update storage.buckets set file_size_limit = 6 * 1024 * 1024,  allowed_mime_types = array['image/jpeg','image/webp'] where id = 'previews';
    update storage.buckets set file_size_limit = 12 * 1024 * 1024, allowed_mime_types = array['image/jpeg','image/png','image/webp'] where id = 'renders';
    update storage.buckets set file_size_limit = 20 * 1024 * 1024, allowed_mime_types = array['application/pdf','image/png'] where id in ('contracts','print');
  end if;
end $$;

-- ---------- הצטרפות עצמית: בקשה, ואישור שיוצר ארגון ומשייך ----------
alter table applications add column if not exists user_id uuid default auth.uid();
alter table applications add column if not exists note text;
create unique index if not exists applications_one_open on applications (created_by) where status = 'new';

create or replace function application_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.kind::text not in ('gallery','artist','winery','printer') then raise exception 'סוג הצטרפות לא מוכר'; end if;
    if length(coalesce(new.name,'')) not between 2 and 80 or length(coalesce(new.details,'')) > 600
       or length(coalesce(new.site,'')) > 200 or length(coalesce(new.contact,'')) > 120 or length(coalesce(new.why,'')) > 600 then
      raise exception 'אחד השדות ארוך מדי או חסר'; end if;
    new.status := 'new'; new.created_by := auth.uid(); new.user_id := auth.uid();
  end if;
  return new;
end $$;
drop trigger if exists application_guard_t on applications;
create trigger application_guard_t before insert on applications for each row execute function application_guard();

create or replace function application_decide(p_id bigint, p_ok boolean, p_gallery uuid default null, p_note text default null) returns text
language plpgsql security definer set search_path = public as $$
declare a applications; org uuid;
begin
  if coalesce(my_role()::text, '') not in ('admin','curator') then raise exception 'רק מנהל או אוצר מאשרים הצטרפות'; end if;
  select * into a from applications where id = p_id for update;
  if not found or a.status <> 'new' then raise exception 'הבקשה כבר טופלה'; end if;
  if not p_ok then
    update applications set status = 'rejected', note = left(p_note, 500) where id = p_id;
    if a.user_id is not null then perform notify_users(null, null, a.user_id, 'בקשת ההצטרפות לא אושרה' || coalesce(': ' || p_note, '')); end if;
    return 'rejected';
  end if;
  perform set_config('app.bypass', '1', true);
  if a.kind::text = 'artist' then
    if p_gallery is null then select id into p_gallery from organizations where kind = 'gallery' order by created_at limit 1; end if;
    if a.user_id is not null then
      update profiles set role = 'artist', status = 'active', org_id = null where id = a.user_id and role is null;
      insert into artists (user_id, gallery_id, name) select a.user_id, p_gallery, a.name
      where not exists (select 1 from artists where user_id = a.user_id);
    end if;
  else
    insert into organizations (kind, name, details) values (a.kind, a.name,
      jsonb_build_object('site', a.site, 'contact', a.contact, 'about', a.details)) returning id into org;
    if a.user_id is not null then
      update profiles set role = a.kind, status = 'active', org_id = org where id = a.user_id and role is null;
    end if;
  end if;
  update applications set status = 'approved', note = left(p_note, 500) where id = p_id;
  if a.user_id is not null then perform notify_users(null, null, a.user_id, 'בקשת ההצטרפות אושרה. אפשר להתחיל'); end if;
  return 'approved';
end $$;
grant execute on function application_decide(bigint, boolean, uuid, text) to authenticated;

-- ---------- מדידת שימוש: ספירות בלבד, בלי מזהה משתמש ----------
create table if not exists usage_daily (
  day   date not null default current_date,
  event text not null,
  role  text not null default '',
  n     int  not null default 0,
  primary key (day, event, role)
);
alter table usage_daily enable row level security;
drop policy if exists usage_read on usage_daily;
create policy usage_read on usage_daily for select to authenticated using (is_admin());

create or replace function track(p_event text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_event !~ '^[a-z_]{2,32}$' then return; end if;
  insert into usage_daily (event, role, n) values (p_event, coalesce(my_role()::text, 'guest'), 1)
  on conflict (day, event, role) do update set n = usage_daily.n + 1;
end $$;
grant execute on function track(text) to authenticated, anon;

-- ---------- בדיקת תקינות לשירות ניטור חיצוני ----------
create or replace function health() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('db', true, 'engine_breaker', engine_breaker_open(),
    'engine_budget_used_pct', round(100 * engine_spend_month() / nullif((select engine_budget from settings where id = 1), 0)),
    'jobs_dead_24h', (select count(*) from jobs where state = 'dead' and created_at > now() - interval '24 hours'),
    'at', now())
$$;
grant execute on function health() to anon, authenticated;

-- =====================================================================
--  שלב 5 · ניטור שגיאות בלי שירות חיצוני
--  שגיאות מהדפדפן נספרות לפי סוג, בלי פרטי משתמש
-- =====================================================================
create table if not exists client_errors (
  id       bigint generated by default as identity primary key,
  sig      text not null unique,          -- טביעת אצבע של ההודעה והמקום
  message  text not null,
  place    text,
  role     text,
  n        int not null default 1,
  first_at timestamptz not null default now(),
  last_at  timestamptz not null default now(),
  resolved boolean not null default false
);
alter table client_errors enable row level security;
drop policy if exists cerr_admin on client_errors;
create policy cerr_admin on client_errors for all to authenticated using (is_admin()) with check (is_admin());

create or replace function log_error(p_message text, p_place text default null) returns void
language plpgsql security definer set search_path = public as $$
declare m text; pl text; s text;
begin
  -- בלי פרטים אישיים: כתובות מייל, מספרים ארוכים ומזהים מוחלפים
  m := left(regexp_replace(regexp_replace(regexp_replace(coalesce(p_message,''),
         '[\w.+-]+@[\w-]+\.[\w.]+', '<email>', 'g'),
         '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', '<id>', 'gi'),
         '\d{5,}', '<n>', 'g'), 300);
  pl := left(regexp_replace(coalesce(p_place,''), '\?.*$', ''), 120);
  if m = '' then return; end if;
  s := md5(m || '|' || pl);
  insert into client_errors (sig, message, place, role) values (s, m, pl, coalesce(my_role()::text, 'guest'))
  on conflict (sig) do update set n = client_errors.n + 1, last_at = now(),
    resolved = case when client_errors.last_at < now() - interval '1 day' then false else client_errors.resolved end;
end $$;
grant execute on function log_error(text, text) to authenticated, anon;

create or replace function health() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('db', true, 'engine_breaker', engine_breaker_open(),
    'engine_budget_used_pct', round(100 * engine_spend_month() / nullif((select engine_budget from settings where id = 1), 0)),
    'jobs_dead_24h', (select count(*) from jobs where state = 'dead' and created_at > now() - interval '24 hours'),
    'client_errors_1h', (select coalesce(sum(n), 0) from client_errors where last_at > now() - interval '1 hour' and not resolved),
    'at', now())
$$;
grant execute on function health() to anon, authenticated;

-- =====================================================================
--  שלב 6 · בדיקת קובץ אוטומטית במקום בדיקה ידנית של האוצרת
--  השרת אוכף את אותם כללים: מספיק פיקסלים לתווית, בלי כפילויות.
--  אישור הגלריה מפרסם ישר למאגר; העלאה של הגלריה עצמה מתפרסמת מיד.
-- =====================================================================
alter table works add column if not exists phash text;
alter table works add column if not exists file_check jsonb;
create index if not exists works_phash_idx on works (phash) where phash is not null;

-- DPI על אזור הציור בתווית רגילה (72×93 מ״מ)
create or replace function label_dpi(w int, h int) returns int
language sql immutable as $$ select floor(least(w / (72 / 25.4), h / (93 / 25.4)))::int $$;

create or replace function hamming64(a text, b text) returns int
language sql immutable as $$
  select bit_count(('x' || lpad(a, 16, '0'))::bit(64) # ('x' || lpad(b, 16, '0'))::bit(64))::int
$$;

create or replace function guard_work() returns trigger
language plpgsql security definer set search_path = public as $$
declare r text := coalesce(my_role()::text, ''); d works;
begin
  if tg_op = 'INSERT' and auth.uid() is not null then
    -- בדיקת הקובץ: אותם כללים כמו בדפדפן
    if new.px_w is null or new.px_h is null then raise exception 'חסרים נתוני הקובץ. כדאי להעלות שוב'; end if;
    if label_dpi(new.px_w, new.px_h) < 240 then
      raise exception 'הרזולוציה נמוכה מדי להדפסה: % DPI על התווית, וצריך לפחות 240', label_dpi(new.px_w, new.px_h); end if;
    if new.phash is not null and new.phash !~ '^[0-9a-f]{16}$' then raise exception 'טביעת האצבע של התמונה לא תקינה'; end if;
    select * into d from works where phash is not null and new.phash is not null and hamming64(phash, new.phash) <= 5 limit 1;
    if found then raise exception 'היצירה כבר נמצאת במאגר: "%"', d.title; end if;
  end if;
  if r not in ('curator','admin') and auth.uid() is not null then
    if tg_op = 'INSERT' then
      new.pick_rank := null;
      -- גלריה שמעלה בעצמה כבר אישרה: הקובץ נבדק, אז היצירה עולה ישר למאגר
      new.status := case when r = 'gallery' then 'live' else 'pending' end;
    elsif new.status is distinct from old.status and r = 'gallery'
          and old.status in ('pending','review') and new.status in ('live','rejected') then
      null;   -- אישור הגלריה מפרסם; הבדיקה הטכנית כבר נעשתה בהעלאה
    elsif new.status is distinct from old.status and new.status in ('live','review','rejected') then
      raise exception 'רק הגלריה מאשרת יצירות';
    elsif new.pick_rank is distinct from old.pick_rank then
      new.pick_rank := old.pick_rank;
    end if;
    if tg_op = 'UPDATE' and (new.phash is distinct from old.phash or new.px_w is distinct from old.px_w or new.px_h is distinct from old.px_h)
       and r <> 'gallery' and old.status = 'live' then
      raise exception 'אי אפשר להחליף את הקובץ של יצירה שכבר פורסמה';
    end if;
  end if;
  return new;
end $$;

-- יצירות שחיכו לבדיקה ידנית: אם הקובץ מתאים, הן עוברות למאגר
update works set status = 'live'
where status = 'review' and px_w is not null and px_h is not null and label_dpi(px_w, px_h) >= 240;

-- =====================================================================
--  שלב 7 · פעולות אוטומטיות בלי מגע אדם
--  תמחור אוטומטי, אישור הזמנות, דפוס אחרי תשלום, מספרי חשבונית,
--  בלעדיות, תזכורות, סגירת בקשות תקועות, סוף רישיון, המלצות לפי פופולריות,
--  שמירת פרטי לקוחות לתקופה מוגבלת, בדיקת צילומים, תזמון יומי
-- =====================================================================

-- ---------- הגדרות: כל אוטומציה ניתנת לכיבוי ----------
alter table organizations add column if not exists auto_price   boolean not null default false; -- גלריה: לתמחר לפי הנוסחה מיד
alter table organizations add column if not exists auto_approve boolean not null default false; -- יקב: לאשר הזמנות לקוח מיד
alter table organizations add column if not exists auto_print   boolean not null default true;  -- יקב: לשלוח לדפוס מיד אחרי תשלום
alter table settings add column if not exists auto_picks boolean not null default true;          -- המלצות לפי פופולריות
alter table settings add column if not exists stale_days int not null default 3;                 -- תזכורת אחרי
alter table settings add column if not exists cancel_days int not null default 30;               -- סגירה אחרי
alter table settings add column if not exists customer_retention_days int;                       -- ריק = לא מוחקים (עורך הדין יקבע)
alter table works add column if not exists pop_score numeric not null default 0;
alter table works add column if not exists excl_lock boolean not null default false;
alter table renders add column if not exists auto_check jsonb;
alter table customer_orders add column if not exists updated_at timestamptz not null default now();

create table if not exists reminders (
  entity    text   not null,
  entity_id bigint not null,
  kind      text   not null,
  at        timestamptz not null default now(),
  primary key (entity, entity_id, kind)
);
alter table reminders enable row level security;
drop policy if exists rem_admin on reminders;
create policy rem_admin on reminders for select to authenticated using (is_admin());

create or replace function corders_touch() returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
drop trigger if exists corders_touch_t on customer_orders;
create trigger corders_touch_t before update on customer_orders for each row execute function corders_touch();

-- ---------- 1. תמחור אוטומטי ----------
create or replace function deal_auto_price(p_deal bigint) returns void
language plpgsql security definer set search_path = public as $$
declare x deals; s settings; ar artists;
begin
  select * into x from deals where id = p_deal for update;
  if x.status <> 'sent' then return; end if;
  select * into s from settings where id = 1;
  x.adj_pct := 0;
  update deals set adj_pct = 0, comm_pct = s.comm_pct, price_net = deal_price(x), status = 'priced',
         note = 'תומחר אוטומטית לפי הנוסחה', updated_at = now() where id = p_deal;
  select * into ar from artists where id = x.artist_id;
  if ar.pre_consent and x.license_type = 'one' and x.qty_tier = 'a' and not x.exclusive then
    update deals set status = 'sign', updated_at = now() where id = p_deal;
    perform deal_make_contract(p_deal);
    perform notify_deal(p_deal, 'המחיר אושר מראש. נשאר שהיינן והאמן או הגלריה יאשרו את התווית, ואז חותמים', array['winery','artist','gallery']::app_role[]);
  else
    perform notify_deal(p_deal, 'הבקשה תומחרה אוטומטית. נדרשת הסכמת האמן', array['artist']::app_role[]);
  end if;
  insert into audit_log (actor, action, entity, entity_id) values (null, 'auto_price', 'deal', p_deal::text);
end $$;
revoke execute on function deal_auto_price(bigint) from public, anon, authenticated;

create or replace function deals_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (select auto_price from organizations where id = new.gallery_id) then perform deal_auto_price(new.id); end if;
  return null;
end $$;
drop trigger if exists deals_auto_price_t on deals;
create trigger deals_auto_price_t after insert on deals for each row execute function deals_after_insert();

-- ---------- 3 + 7. אחרי תשלום: דפוס אוטומטי. בלעדיות נועלת ומשחררת את היצירה ----------
create or replace function work_refresh_available(p_work bigint) returns void
language plpgsql security definer set search_path = public as $$
declare locked boolean;
begin
  locked := exists (select 1 from deals where work_id = p_work and exclusive and status in ('active','pay','sign')
                    and coalesce(ends_at, current_date + 1) >= current_date);
  if locked then
    update works set available = false, excl_lock = true where id = p_work and (available or not excl_lock);
  else
    update works set available = true, excl_lock = false where id = p_work and excl_lock;
  end if;
end $$;
revoke execute on function work_refresh_available(bigint) from public, anon, authenticated;

create or replace function deals_after_update() returns trigger
language plpgsql security definer set search_path = public as $$
declare pr uuid;
begin
  if new.status is distinct from old.status then
    if new.exclusive then perform work_refresh_available(new.work_id); end if;
    if new.status = 'active' and (select auto_print from organizations where id = new.winery_id) then
      select id into pr from organizations where kind = 'printer' and active order by created_at limit 1;
      insert into print_orders (deal_id, printer_id, due) values (new.id, pr, current_date + 21) on conflict (deal_id) do nothing;
      if found then
        perform notify_deal(new.id, 'התשלום אושר. ההזמנה נשלחה לבית הדפוס', array['winery']::app_role[]);
        if pr is not null then perform notify_users(pr, 'printer', null, 'הזמנת דפוס חדשה לעסקה ' || new.id); end if;
      end if;
    end if;
  end if;
  return null;
end $$;
drop trigger if exists deals_after_update_t on deals;
create trigger deals_after_update_t after update of status on deals for each row execute function deals_after_update();

-- ---------- 2 + 3. הזמנות לקוח: אישור מיד, ודפוס מיד אחרי תשלום ----------
create or replace function corders_auto() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  -- אחרי תשלום: ישר לדפוס, אם היקב בחר בזה
  if old.paid_at is null and new.paid_at is not null and new.status = 'approved'
     and (select auto_print from organizations where id = new.winery_id) then
    new.status := 'print';
    new.log := coalesce(new.log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', 'ההזמנה עברה לדפוס אוטומטית', 'at', now()));
    if new.customer_id is not null then perform notify_users(null, null, new.customer_id, 'ההזמנה עברה לדפוס'); end if;
  end if;
  return new;
end $$;
drop trigger if exists corders_auto_t on customer_orders;
create trigger corders_auto_t before update of paid_at on customer_orders for each row execute function corders_auto();

-- הזמנה חדשה: אישור מיד, אם היקב בחר בזה (אחרי ההכנסה, כדי שהרשאת הלקוח תישאר "נשלחה")
create or replace function corders_auto_approve() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (select auto_approve from organizations where id = new.winery_id) then
    update customer_orders set status = 'approved',
      log = coalesce(log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', 'ההזמנה אושרה אוטומטית', 'at', now()))
    where id = new.id;
    if new.customer_id is not null then perform notify_users(null, null, new.customer_id, 'ההזמנה אושרה. היקב יחזור אליך לגבי התשלום'); end if;
  end if;
  return null;
end $$;
drop trigger if exists corders_auto_approve_t on customer_orders;
create trigger corders_auto_approve_t after insert on customer_orders for each row execute function corders_auto_approve();

-- ---------- 4. מספרי חשבונית רצים ----------
create sequence if not exists invoice_seq;
create or replace function invoice_number() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.number is null or new.number = '' then
    new.number := 'INV-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('invoice_seq')::text, 4, '0');
  end if;
  return new;
end $$;
drop trigger if exists invoice_number_t on invoices;
create trigger invoice_number_t before insert on invoices for each row execute function invoice_number();
update invoices set number = 'INV-' || to_char(created_at, 'YYYY') || '-' || lpad(nextval('invoice_seq')::text, 4, '0')
where number is null or number = '';

-- ---------- תזכורת אחת לכל מצב, לא יותר מפעם בכמה ימים ----------
create or replace function remind_once(p_entity text, p_id bigint, p_kind text, p_every interval) returns boolean
language plpgsql security definer set search_path = public as $$
declare last timestamptz;
begin
  select at into last from reminders where entity = p_entity and entity_id = p_id and kind = p_kind;
  if found and (p_every is null or last > now() - p_every) then return false; end if;
  insert into reminders (entity, entity_id, kind) values (p_entity, p_id, p_kind)
  on conflict (entity, entity_id, kind) do update set at = now();
  return true;
end $$;
revoke execute on function remind_once(text,bigint,text,interval) from public, anon, authenticated;

-- ---------- 5 + 6 + 8 + 9 + 13. העבודה היומית ----------
create or replace function daily_maintenance() returns jsonb
language plpgsql security definer set search_path = public as $$
declare s settings; d record; o record; n_rem int := 0; n_cancel int := 0; n_end int := 0; n_co int := 0; n_anon int := 0;
  st interval; ca interval; who app_role[]; msg text;
begin
  select * into s from settings where id = 1;
  st := make_interval(days => s.stale_days); ca := make_interval(days => s.cancel_days);

  -- בקשות רישיון שלא זזו: סגירה אחרי תקופה, תזכורת לפני
  for d in select * from deals where status in ('sent','priced','sign') and updated_at < now() - ca loop
    update deals set status = 'cancelled', note = 'נסגרה אוטומטית אחרי ' || s.cancel_days || ' יום בלי תגובה', updated_at = now() where id = d.id;
    perform notify_deal(d.id, 'הבקשה נסגרה אוטומטית אחרי ' || s.cancel_days || ' יום בלי תגובה', array['winery','gallery']::app_role[]);
    n_cancel := n_cancel + 1;
  end loop;
  for d in select * from deals where status in ('sent','priced','sign','pay') and updated_at < now() - st loop
    who := case d.status when 'sent' then array['gallery'] when 'priced' then array['artist'] when 'sign' then array['winery'] else array['gallery','winery'] end::app_role[];
    msg := case d.status when 'sent' then 'תזכורת: בקשת רישיון מחכה לתמחור'
                         when 'priced' then 'תזכורת: בקשת רישיון מחכה להסכמת האמן'
                         when 'sign' then 'תזכורת: החוזה מחכה לחתימה'
                         else 'תזכורת: עסקה מחכה לתשלום' end;
    if remind_once('deal', d.id, 'stale:' || d.status, st) then perform notify_deal(d.id, msg, who); n_rem := n_rem + 1; end if;
  end loop;

  -- סוף רישיון: התראה 60 ו-30 יום לפני, הודעה כשנגמר, ושחרור בלעדיות
  for d in select * from deals where status = 'active' and ends_at is not null loop
    if d.ends_at < current_date then
      if remind_once('deal', d.id, 'ended', null) then
        perform notify_deal(d.id, 'הרישיון הסתיים. יש שישה חודשים למכירת מלאי שכבר הודפס', array['winery','gallery','artist']::app_role[]);
        if d.exclusive then perform work_refresh_available(d.work_id); end if;
        n_end := n_end + 1;
      end if;
    elsif d.ends_at <= current_date + 30 then
      if remind_once('deal', d.id, 'end30', null) then perform notify_deal(d.id, 'הרישיון מסתיים בעוד פחות מחודש. אפשר לחדש מחדר העסקה', array['winery','gallery']::app_role[]); n_rem := n_rem + 1; end if;
    elsif d.ends_at <= current_date + 60 then
      if remind_once('deal', d.id, 'end60', null) then perform notify_deal(d.id, 'הרישיון מסתיים בעוד חודשיים', array['winery','gallery']::app_role[]); n_rem := n_rem + 1; end if;
    end if;
  end loop;

  -- הזמנות לקוח שלא זזו
  for o in select * from customer_orders where status in ('sent','review','label') and updated_at < now() - ca loop
    update customer_orders set status = 'cancel',
      log = log || jsonb_build_array(jsonb_build_object('t', 'ההזמנה נסגרה אוטומטית אחרי ' || s.cancel_days || ' יום בלי תגובה', 'at', now())) where id = o.id;
    perform notify_users(o.winery_id, 'winery', null, 'הזמנת לקוח ' || o.id || ' נסגרה אחרי ' || s.cancel_days || ' יום בלי תגובה');
    if o.customer_id is not null then perform notify_users(null, null, o.customer_id, 'ההזמנה נסגרה כי לא הייתה תגובה זמן רב. אפשר לשלוח אותה שוב'); end if;
    n_cancel := n_cancel + 1;
  end loop;
  for o in select * from customer_orders where status = 'sent' and updated_at < now() - st loop
    if remind_once('corder', o.id, 'stale:sent', st) then perform notify_users(o.winery_id, 'winery', null, 'תזכורת: הזמנת לקוח ' || o.id || ' מחכה לאישור'); n_co := n_co + 1; end if;
  end loop;
  for o in select * from customer_orders where status = 'review' and updated_at < now() - st and customer_id is not null loop
    if remind_once('corder', o.id, 'stale:review', st) then perform notify_users(null, null, o.customer_id, 'תזכורת: היקב הציע התאמות להזמנה שלך, והן מחכות לאישורך'); n_co := n_co + 1; end if;
  end loop;
  for o in select * from customer_orders where status = 'label' and updated_at < now() - st loop
    if remind_once('corder', o.id, 'stale:label', st) then perform label_notify('corder', o.id, 'תזכורת: תווית של לקוח מחכה לאישור שלך', array['art']); n_co := n_co + 1; end if;
  end loop;
  for o in select * from customer_orders where status = 'approved' and paid_at is null and updated_at < now() - st loop
    if remind_once('corder', o.id, 'stale:unpaid', st) then perform notify_users(o.winery_id, 'winery', null, 'תזכורת: הזמנת לקוח ' || o.id || ' אושרה ומחכה לתשלום'); n_co := n_co + 1; end if;
  end loop;

  -- המלצות לפי פופולריות: ניסיונות על בקבוק, רישיונות והזמנות ב-90 הימים האחרונים
  update works w set pop_score = coalesce(t.n, 0) + 5 * coalesce(l.n, 0) + 2 * coalesce(c.n, 0)
  from works w2
  left join (select work_id, count(*) n from designs where created_at > now() - interval '90 days' group by work_id) t on t.work_id = w2.id
  left join (select work_id, count(*) n from deals where created_at > now() - interval '90 days' and status not in ('rejected','cancelled') group by work_id) l on l.work_id = w2.id
  left join (select (design ->> 'work')::bigint work_id, count(*) n from customer_orders where created_at > now() - interval '90 days' and status <> 'cancel' group by 1) c on c.work_id = w2.id
  where w.id = w2.id;
  if s.auto_picks then
    update works w set pick_rank = r.rk from (
      select id, case when rn <= 8 and pop_score > 0 then rn end rk
      from (select id, pop_score, row_number() over (order by pop_score desc, id) rn from works where status = 'live' and available) z) r
    where w.id = r.id and w.pick_rank is distinct from r.rk;
  end if;

  -- פרטי לקוחות בהזמנות שהסתיימו נמחקים אחרי תקופה שנקבעה (כבוי עד שעורך הדין יקבע)
  if s.customer_retention_days is not null then
    update customer_orders set cust = jsonb_build_object('n', 'לקוח')
    where status in ('done','cancel') and updated_at < now() - make_interval(days => s.customer_retention_days)
      and cust ->> 'n' is distinct from 'לקוח';
    get diagnostics n_anon = row_count;
  end if;

  insert into audit_log (actor, action, entity, data) values (null, 'daily', 'system',
    jsonb_build_object('reminders', n_rem, 'cancelled', n_cancel, 'ended', n_end, 'orders', n_co, 'anonymized', n_anon));
  return jsonb_build_object('reminders', n_rem, 'cancelled', n_cancel, 'ended', n_end, 'orders', n_co, 'anonymized', n_anon);
end $$;
revoke execute on function daily_maintenance() from public, anon, authenticated;

-- ---------- 10. בדיקת צילום אוטומטית: התוצאה נשמרת, ומה שתואם מאושר ----------
create or replace function render_auto_check(p_path text, p_match boolean, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
begin
  update renders set auto_check = jsonb_build_object('match', p_match, 'reason', left(coalesce(p_reason,''), 200), 'at', now()),
                     approved = case when p_match then true else approved end
  where image_path = p_path and created_by = auth.uid() and approved is null;
end $$;
grant execute on function render_auto_check(text, boolean, text) to authenticated;

-- ---------- 12. דוח חודשי לגלריה ולאמן ----------
create or replace function monthly_statement(p_month date) returns table (
  deal_id bigint, paid_at date, winery text, work text, artist text, net numeric, platform numeric, artist_share numeric, gallery_share numeric)
language sql stable security definer set search_path = public as $$
  select d.id, d.paid_at, wo.name, w.title, a.name, d.price_net,
         round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100),
         round((d.price_net - round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100)) * s.artist_share / 100),
         d.price_net - round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100)
           - round((d.price_net - round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100)) * s.artist_share / 100)
  from deals d join works w on w.id = d.work_id join artists a on a.id = d.artist_id
       join organizations wo on wo.id = d.winery_id cross join settings s
  where d.paid_at >= date_trunc('month', p_month) and d.paid_at < date_trunc('month', p_month) + interval '1 month'
    and (is_admin() or (my_role()::text = 'gallery' and d.gallery_id = my_org()) or d.artist_id = my_artist())
  order by d.paid_at, d.id
$$;
grant execute on function monthly_statement(date) to authenticated;

-- ---------- תזמון יומי (פועל כשהתוסף pg_cron מופעל ב-Supabase) ----------
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'daily-maintenance';
    perform cron.schedule('daily-maintenance', '17 1 * * *', 'select public.daily_maintenance()');
  end if;
end $$;

-- =====================================================================
--  שלב 8 · אישור תווית בסבבים: היינן והאמן או הגלריה, אף פעם לא אוטומטי
--  כל צד מאשר, מבקש שינוי או מוסיף הערה. כל שינוי פותח סבב חדש,
--  ומאפס את שני האישורים. בלי שני האישורים אין חתימה ואין דפוס.
-- =====================================================================

-- אישור אוטומטי של הזמנות לקוח בוטל: האישור הסופי של התווית תמיד ידני
drop trigger if exists corders_auto_approve_t on customer_orders;
update organizations set auto_approve = false where auto_approve;

alter table deals add column if not exists label_round int not null default 1;
alter table deals add column if not exists label_ok_w int;
alter table deals add column if not exists label_ok_a int;
alter table customer_orders add column if not exists label_round int not null default 1;
alter table customer_orders add column if not exists label_ok_w int;
alter table customer_orders add column if not exists label_ok_a int;
alter table customer_orders drop constraint if exists customer_orders_status_check;
alter table customer_orders add constraint customer_orders_status_check
  check (status in ('sent','review','label','approved','print','done','cancel'));

create table if not exists label_notes (
  id         bigint generated by default as identity primary key,
  entity     text   not null check (entity in ('deal','corder')),
  entity_id  bigint not null,
  round      int    not null,
  author     uuid   default auth.uid(),
  side       text   not null check (side in ('winery','art','customer','system')),
  kind       text   not null check (kind in ('comment','change','approve','round')),
  body       text   check (length(body) <= 1000),
  created_at timestamptz not null default now()
);
create index if not exists label_notes_idx on label_notes (entity, entity_id, id);
alter table label_notes enable row level security;

-- מי אני מול התווית הזו: יקב, צד האמן (אמן או הגלריה שלו), לקוח
create or replace function label_side(p_entity text, p_id bigint) returns text
language plpgsql stable security definer set search_path = public as $$
declare r text := coalesce(my_role()::text, ''); d deals; o customer_orders; a artists;
begin
  if p_entity = 'deal' then
    select * into d from deals where id = p_id; if not found then return null; end if;
    if r = 'winery' and d.winery_id = my_org() then return 'winery'; end if;
    if (r = 'gallery' and d.gallery_id = my_org()) or d.artist_id = my_artist() then return 'art'; end if;
  else
    select * into o from customer_orders where id = p_id; if not found then return null; end if;
    if r = 'winery' and o.winery_id = my_org() then return 'winery'; end if;
    select * into a from artists where id = (coalesce(o.winery_design, o.design) ->> 'artist')::uuid;
    if found and ((r = 'gallery' and a.gallery_id = my_org()) or a.user_id = auth.uid()) and (o.status in ('label','approved','print','done') or o.label_round > 1) then return 'art'; end if;
    if o.customer_id = auth.uid() then return 'customer'; end if;
  end if;
  if is_admin() then return 'admin'; end if;
  return null;
end $$;
grant execute on function label_side(text, bigint) to authenticated;

drop policy if exists ln_read on label_notes;
create policy ln_read on label_notes for select to authenticated using (label_side(entity, entity_id) is not null);

-- הצד של האמן רואה את הזמנות הלקוחות שמחכות לאישור התווית שלו
drop policy if exists co_art on customer_orders;
create policy co_art on customer_orders for select to authenticated using (
  (status in ('label','approved','print','done') or label_round > 1) and exists (
    select 1 from artists a where a.id = (coalesce(winery_design, design) ->> 'artist')::uuid
      and ((my_role()::text = 'gallery' and a.gallery_id = my_org()) or a.user_id = auth.uid())));

create or replace function label_notify(p_entity text, p_id bigint, msg text, p_to text[]) returns void
language plpgsql security definer set search_path = public as $$
declare o customer_orders; a artists;
begin
  if p_entity = 'deal' then
    perform notify_deal(p_id, msg, (select array_agg(x) from unnest(array[
      case when 'winery' = any(p_to) then 'winery' end, case when 'art' = any(p_to) then 'artist' end,
      case when 'art' = any(p_to) then 'gallery' end]) x where x is not null)::app_role[]);
  else
    select * into o from customer_orders where id = p_id;
    if 'winery' = any(p_to) then perform notify_users(o.winery_id, 'winery', null, msg); end if;
    if 'customer' = any(p_to) and o.customer_id is not null then perform notify_users(null, null, o.customer_id, msg); end if;
    if 'art' = any(p_to) then
      select * into a from artists where id = (coalesce(o.winery_design, o.design) ->> 'artist')::uuid;
      if found then
        perform notify_users(a.gallery_id, 'gallery', null, msg);
        if a.user_id is not null then perform notify_users(null, null, a.user_id, msg); end if;
      end if;
    end if;
  end if;
end $$;
revoke execute on function label_notify(text,bigint,text,text[]) from public, anon, authenticated;

-- הפעולה: לאשר, לבקש שינוי, להוסיף הערה
create or replace function label_action(p_entity text, p_id bigint, p_action text, p_body text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare side text := label_side(p_entity, p_id); rnd int; okw int; oka int; st text; who text;
begin
  if side is null or side = 'admin' and p_action <> 'comment' then raise exception 'אין גישה לתווית הזו'; end if;
  p_body := nullif(left(btrim(coalesce(p_body, '')), 1000), '');
  if p_entity = 'deal' then
    select label_round, label_ok_w, label_ok_a, status::text into rnd, okw, oka, st from deals where id = p_id for update;
    if st in ('active','rejected','cancelled') then raise exception 'העסקה כבר סגורה'; end if;
  else
    select label_round, label_ok_w, label_ok_a, status into rnd, okw, oka, st from customer_orders where id = p_id for update;
    if st in ('print','done','cancel') then raise exception 'ההזמנה כבר בדפוס או סגורה'; end if;
  end if;
  who := case side when 'winery' then 'היינן' when 'art' then 'האמן או הגלריה' else 'הלקוח' end;

  if p_action = 'comment' then
    if p_body is null then raise exception 'ההערה ריקה'; end if;
    insert into label_notes (entity, entity_id, round, side, kind, body) values (p_entity, p_id, rnd, side, 'comment', p_body);
    perform label_notify(p_entity, p_id, 'הערה חדשה על התווית: ' || left(p_body, 80),
      array_remove(array['winery','art', case when p_entity = 'corder' then 'customer' end], side));

  elsif p_action = 'approve' then
    if side not in ('winery','art') then raise exception 'רק היינן והאמן או הגלריה מאשרים את התווית'; end if;
    if p_entity = 'corder' and side = 'art' and st <> 'label' then raise exception 'התווית עוד לא הגיעה לאישור שלך'; end if;
    insert into label_notes (entity, entity_id, round, side, kind, body) values (p_entity, p_id, rnd, side, 'approve', p_body);
    if side = 'winery' then okw := rnd; else oka := rnd; end if;
    if p_entity = 'deal' then
      update deals set label_ok_w = okw, label_ok_a = oka where id = p_id;
    else
      update customer_orders set label_ok_w = okw, label_ok_a = oka where id = p_id;
    end if;
    if okw = rnd and oka = rnd then
      if p_entity = 'corder' then
        update customer_orders set status = 'approved',
          log = log || jsonb_build_array(jsonb_build_object('t', 'התווית אושרה על ידי היינן והאמן', 'at', now())) where id = p_id;
        perform label_notify(p_entity, p_id, 'התווית אושרה סופית. אפשר לעבור לתשלום', array['winery','customer','art']);
      else
        perform label_notify(p_entity, p_id, 'התווית אושרה על ידי שני הצדדים', array['winery','art']);
      end if;
    else
      perform label_notify(p_entity, p_id, who || ' אישר את התווית. מחכים לאישור השני', array_remove(array['winery','art'], side));
    end if;

  elsif p_action = 'change' then
    if side not in ('winery','art') then raise exception 'רק היינן והאמן או הגלריה מבקשים שינוי בתווית'; end if;
    if p_body is null then raise exception 'צריך לכתוב מה לשנות'; end if;
    insert into label_notes (entity, entity_id, round, side, kind, body) values (p_entity, p_id, rnd, side, 'change', p_body);
    rnd := rnd + 1;
    insert into label_notes (entity, entity_id, round, side, kind, body) values (p_entity, p_id, rnd, 'system', 'round', 'סבב ' || rnd);
    if p_entity = 'deal' then
      update deals set label_round = rnd, label_ok_w = null, label_ok_a = null where id = p_id;
    else
      update customer_orders set label_round = rnd, label_ok_w = null, label_ok_a = null,
        status = case when status in ('label','approved') then 'sent' else status end,
        log = log || jsonb_build_array(jsonb_build_object('t', who || ' ביקש שינוי בתווית', 'at', now())) where id = p_id;
    end if;
    perform label_notify(p_entity, p_id, who || ' ביקש שינוי בתווית: ' || left(p_body, 80), array_remove(array['winery','art'], side));
  else
    raise exception 'פעולה לא מוכרת';
  end if;

  return jsonb_build_object('round', rnd, 'ok_w', okw, 'ok_a', oka);
end $$;
grant execute on function label_action(text, bigint, text, text) to authenticated;

-- חתימה על חוזה רק אחרי ששני הצדדים אישרו את התווית בסבב הנוכחי
create or replace function deals_label_gate() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.status = 'sign' and new.status = 'pay'
     and not (coalesce(old.label_ok_w, 0) = old.label_round and coalesce(old.label_ok_a, 0) = old.label_round) then
    raise exception 'לפני החתימה צריך שהיינן והאמן או הגלריה יאשרו את התווית';
  end if;
  return new;
end $$;
drop trigger if exists deals_label_gate_t on deals;
create trigger deals_label_gate_t before update of status on deals for each row execute function deals_label_gate();

-- היקב ערך את העיצוב של עסקה פתוחה: נפתח סבב חדש והאישורים מתאפסים
create or replace function designs_new_round() returns trigger
language plpgsql security definer set search_path = public as $$
declare d record;
begin
  if (new.pos, new.zoom, new.layout, new.work_id, new.wine_id) is not distinct from (old.pos, old.zoom, old.layout, old.work_id, old.wine_id) then return new; end if;
  for d in select id, label_round from deals where design_code = new.code and status in ('sent','priced','sign') loop
    update deals set label_round = d.label_round + 1, label_ok_w = null, label_ok_a = null where id = d.id;
    insert into label_notes (entity, entity_id, round, side, kind, body) values ('deal', d.id, d.label_round + 1, 'system', 'round', 'סבב ' || (d.label_round + 1) || ': היקב עדכן את העיצוב');
    perform label_notify('deal', d.id, 'גרסה חדשה של התווית מחכה לאישור', array['art']);
  end loop;
  return new;
end $$;
drop trigger if exists designs_new_round_t on designs;
create trigger designs_new_round_t after update on designs for each row execute function designs_new_round();

-- =====================================================================
--  שלב 9 · לכל החלטה של אדם יש המשך: דחייה, ביטול ובקשת תיקון מהדפוס
-- =====================================================================

-- עסקה שנדחתה או בוטלה: כל הצדדים מקבלים הודעה עם הסיבה
create or replace function deals_closed_notify() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = old.status then return new; end if;
  if new.status = 'cancelled' then
    perform notify_deal(new.id, 'העסקה נסגרה: ' || coalesce(new.note, 'היקב ביטל את הבקשה'), array['gallery','artist']::app_role[]);
  elsif new.status = 'rejected' then
    perform notify_deal(new.id, 'הבקשה נדחתה' || coalesce(': ' || new.note, ''), array['gallery','artist']::app_role[]);
  end if;
  return new;
end $$;
drop trigger if exists deals_closed_notify_t on deals;
create trigger deals_closed_notify_t after update of status on deals for each row execute function deals_closed_notify();

-- בית הדפוס מבקש תיקון קבצים: הודעה בשיחה של העסקה, והתראה לגלריה וליקב
create or replace function print_issue(p_deal bigint, p_note text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(my_role()::text, '') <> 'printer' or not can_see_deal(p_deal) then raise exception 'אין הרשאה'; end if;
  p_note := nullif(left(btrim(coalesce(p_note, '')), 500), '');
  if p_note is null then raise exception 'צריך לכתוב מה לתקן'; end if;
  insert into deal_messages (deal_id, sender, sender_role, body)
  values (p_deal, auth.uid(), 'printer', 'בית הדפוס מבקש תיקון קבצים: ' || p_note);
  perform notify_deal(p_deal, 'בית הדפוס מבקש תיקון קבצים', array['gallery','winery']::app_role[]);
end $$;
revoke execute on function print_issue(bigint, text) from public, anon;
grant execute on function print_issue(bigint, text) to authenticated;

-- אמן ששולח שוב יצירה שהוחזרה: ההערה הקודמת נמחקת והגלריה מקבלת הודעה
create or replace function works_resent() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.status = 'rejected' and new.status = 'pending' then
    new.review_note := null;
    perform notify_users((select gallery_id from artists where id = new.artist_id), 'gallery', null,
                         'יצירה שהוחזרה נשלחה שוב לאישור: ' || new.title);
  end if;
  return new;
end $$;
drop trigger if exists works_resent_t on works;
create trigger works_resent_t before update of status on works for each row execute function works_resent();

-- האוצר סימן שצילום לא תואם לתווית: היקב שצילם מקבל הודעה ויכול לצלם שוב
create or replace function renders_mismatch() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.approved is false and old.approved is distinct from false and new.created_by is not null then
    perform notify_users(null, null, new.created_by, 'צילום ההדמיה לא תאם את התווית. כדאי לצלם שוב');
  end if;
  return new;
end $$;
drop trigger if exists renders_mismatch_t on renders;
create trigger renders_mismatch_t after update of approved on renders for each row execute function renders_mismatch();

-- =====================================================================
--  שלב 10 · דרגות אמנים לפי עלות: מתפתח, מבוסס, בכיר, מוזיאלי
--  הדרגה קובעת טווח מחיר לרישיון, חלק האמן, ותוספת לבקבוק ללקוחות.
--  הגלריה ממליצה, מנהל המערכת מאשר.
-- =====================================================================
create table if not exists artist_tiers (
  code         text primary key check (code in ('emerging','established','senior','museum')),
  name         text not null,
  rank         int not null,
  min_price    numeric not null,
  max_price    numeric not null,
  artist_pct   numeric not null check (artist_pct between 0 and 100),
  bottle_addon numeric not null default 0 check (bottle_addon >= 0),
  check (min_price > 0 and min_price <= max_price)
);
alter table artist_tiers enable row level security;
drop policy if exists tiers_read on artist_tiers;
create policy tiers_read on artist_tiers for select to authenticated using (true);
drop policy if exists tiers_admin on artist_tiers;
create policy tiers_admin on artist_tiers for all to authenticated using (is_admin()) with check (is_admin());
insert into artist_tiers (code, name, rank, min_price, max_price, artist_pct, bottle_addon) values
  ('emerging',    'מתפתח',  1,  800,  1999, 45,  8),
  ('established', 'מבוסס',  2, 2000,  3999, 50, 14),
  ('senior',      'בכיר',   3, 4000,  8999, 55, 25),
  ('museum',      'מוזיאלי', 4, 9000, 30000, 60, 45)
on conflict (code) do nothing;

alter table artists add column if not exists tier text not null default 'established' references artist_tiers(code);
alter table artists add column if not exists tier_proposed text references artist_tiers(code);
alter table artists add column if not exists tier_note text;
alter table artists add column if not exists tier_by uuid references profiles(id);
alter table artists add column if not exists tier_at timestamptz;
alter table deals   add column if not exists artist_pct numeric;

-- אמנים קיימים: דרגה לפי מחיר הרצפה שכבר נקבע (פעם אחת בלבד)
update artists a set tier = t.code, tier_at = now()
from artist_tiers t
where a.tier_at is null and a.floor_price between t.min_price and t.max_price;
update artists set tier_at = now() where tier_at is null;

-- רק המנהל משנה דרגה. מחיר הרצפה תמיד בטווח של הדרגה
create or replace function artists_tier_rules() returns trigger
language plpgsql security definer set search_path = public as $$
declare t artist_tiers;
begin
  if tg_op = 'UPDATE' and (new.tier is distinct from old.tier or new.tier_proposed is distinct from old.tier_proposed)
     and not is_admin() and coalesce(current_setting('app.bypass', true), '') <> '1' then
    raise exception 'את הדרגה משנים דרך המלצת הגלריה ואישור המנהל';
  end if;
  select * into t from artist_tiers where code = new.tier;
  if new.floor_price < t.min_price or new.floor_price > t.max_price then
    if tg_op = 'UPDATE' and new.tier is distinct from old.tier then
      new.floor_price := least(greatest(new.floor_price, t.min_price), t.max_price);   -- דרגה חדשה: המחיר נכנס לטווח
    elsif tg_op = 'INSERT' and new.floor_price = 3500 and new.tier <> 'established' then
      new.floor_price := t.min_price;
    else
      raise exception 'מחיר הרצפה לדרגה "%" הוא בין ₪% ל־₪%', t.name, round(t.min_price), round(t.max_price);
    end if;
  end if;
  return new;
end $$;
drop trigger if exists artists_tier_rules_t on artists;
create trigger artists_tier_rules_t before insert or update on artists for each row execute function artists_tier_rules();

-- כל עסקה שומרת את חלק האמן לפי הדרגה ביום הבקשה
create or replace function deals_artist_pct() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.artist_pct is null then
    select t.artist_pct into new.artist_pct from artists a join artist_tiers t on t.code = a.tier where a.id = new.artist_id;
  end if;
  return new;
end $$;
drop trigger if exists deals_artist_pct_t on deals;
create trigger deals_artist_pct_t before insert on deals for each row execute function deals_artist_pct();

-- הגלריה ממליצה על דרגה (מנהל: נקבע מיד)
create or replace function tier_propose(p_artist uuid, p_tier text, p_note text default null) returns text
language plpgsql security definer set search_path = public as $$
declare a artists; t artist_tiers;
begin
  select * into a from artists where id = p_artist for update;
  if not found then raise exception 'האמן לא נמצא'; end if;
  select * into t from artist_tiers where code = p_tier;
  if not found then raise exception 'דרגה לא קיימת'; end if;
  if not (is_admin() or (my_role()::text = 'gallery' and a.gallery_id = my_org())) then raise exception 'אין הרשאה'; end if;
  perform set_config('app.bypass', '1', true);
  if is_admin() then
    update artists set tier = p_tier, tier_proposed = null, tier_note = nullif(left(coalesce(p_note, ''), 500), ''), tier_by = auth.uid(), tier_at = now() where id = p_artist;
    perform notify_users(a.gallery_id, 'gallery', a.user_id, 'הדרגה של ' || a.name || ' נקבעה: ' || t.name);
    return 'set';
  end if;
  if p_tier = a.tier then raise exception 'זו כבר הדרגה של האמן'; end if;
  update artists set tier_proposed = p_tier, tier_note = nullif(left(coalesce(p_note, ''), 500), ''), tier_by = auth.uid() where id = p_artist;
  insert into notifications (user_id, body)
  select id, 'הגלריה ממליצה על דרגה "' || t.name || '" ל' || a.name from profiles where role = 'admin' and status = 'active';
  return 'proposed';
end $$;
grant execute on function tier_propose(uuid, text, text) to authenticated;

-- המנהל מאשר או דוחה את ההמלצה
create or replace function tier_decide(p_artist uuid, p_ok boolean, p_note text default null) returns text
language plpgsql security definer set search_path = public as $$
declare a artists; t artist_tiers;
begin
  if not is_admin() then raise exception 'רק מנהל המערכת מאשר דרגה'; end if;
  select * into a from artists where id = p_artist for update;
  if a.tier_proposed is null then raise exception 'אין המלצה פתוחה'; end if;
  select * into t from artist_tiers where code = a.tier_proposed;
  perform set_config('app.bypass', '1', true);
  if p_ok then
    update artists set tier = a.tier_proposed, tier_proposed = null, tier_at = now() where id = p_artist;
    perform notify_users(a.gallery_id, 'gallery', a.user_id, 'הדרגה של ' || a.name || ' אושרה: ' || t.name);
    return 'approved';
  end if;
  update artists set tier_proposed = null where id = p_artist;
  perform notify_users(a.gallery_id, 'gallery', null, 'ההמלצה על דרגה "' || t.name || '" ל' || a.name || ' לא אושרה' || coalesce(': ' || nullif(p_note, ''), ''));
  return 'rejected';
end $$;
grant execute on function tier_decide(uuid, boolean, text) to authenticated;

-- תוספת לבקבוק ללקוחות: אם היקב לא קבע תוספת לאמן, לפי הדרגה
create or replace function corder_price(p_winery uuid, d jsonb) returns numeric
language plpgsql stable security definer set search_path = public as $$
declare pr jsonb; a text := d ->> 'artist'; addon numeric;
begin
  pr := coalesce((select pricing from organizations where id = p_winery), '{}');
  if a is not null and (pr -> 'artist' ->> a) is null then
    select t.bottle_addon into addon from artists x join artist_tiers t on t.code = x.tier where x.id::text = a;
    if addon is not null then pr := jsonb_set(pr, '{artist}', coalesce(pr -> 'artist', '{}') || jsonb_build_object(a, addon)); end if;
  end if;
  return corder_price_of(pr, d);
end $$;

-- הדוח החודשי: חלק האמן לפי מה שנשמר בעסקה
create or replace function monthly_statement(p_month date) returns table (
  deal_id bigint, paid_at date, winery text, work text, artist text, net numeric, platform numeric, artist_share numeric, gallery_share numeric)
language sql stable security definer set search_path = public as $$
  select d.id, d.paid_at, wo.name, w.title, a.name, d.price_net,
         round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100),
         round((d.price_net - round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100)) * coalesce(d.artist_pct, s.artist_share) / 100),
         d.price_net - round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100)
           - round((d.price_net - round(d.price_net * coalesce(d.comm_pct, s.comm_pct) / 100)) * coalesce(d.artist_pct, s.artist_share) / 100)
  from deals d join works w on w.id = d.work_id join artists a on a.id = d.artist_id
       join organizations wo on wo.id = d.winery_id cross join settings s
  where d.paid_at >= date_trunc('month', p_month) and d.paid_at < date_trunc('month', p_month) + interval '1 month'
    and (is_admin() or (my_role()::text = 'gallery' and d.gallery_id = my_org()) or d.artist_id = my_artist())
  order by d.paid_at, d.id
$$;
grant execute on function monthly_statement(date) to authenticated;

-- =====================================================================
--  שלב 11 · הצהרת זכויות בהעלאת יצירה
--  מי שמעלה מצהיר: הזכויות לשכפול אצל האמן ולא הועברו בכתב,
--  והיצירה לא הוזמנה כדיוקן או כתיעוד של אירוע פרטי (שם הזכויות למזמין).
-- =====================================================================
alter table works add column if not exists rights_ok boolean;
alter table works add column if not exists rights_commission_ok boolean;
alter table works add column if not exists rights_by uuid references profiles(id);
alter table works add column if not exists rights_at timestamptz;

create or replace function works_rights_required() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(my_role()::text, '') in ('admin', 'curator') or auth.uid() is null then return new; end if;
  if tg_op = 'INSERT' then
    if not (coalesce(new.rights_ok, false) and coalesce(new.rights_commission_ok, false)) then
      raise exception 'צריך לאשר את הצהרת הזכויות לפני העלאת יצירה';
    end if;
    new.rights_by := auth.uid(); new.rights_at := now();
  elsif (new.rights_ok, new.rights_commission_ok) is distinct from (old.rights_ok, old.rights_commission_ok) then
    if not (coalesce(new.rights_ok, false) and coalesce(new.rights_commission_ok, false)) then
      raise exception 'אי אפשר לבטל הצהרת זכויות. אם משהו השתנה, פונים למנהל המערכת';
    end if;
    new.rights_by := auth.uid(); new.rights_at := now();
  end if;
  return new;
end $$;
drop trigger if exists works_rights_t on works;
create trigger works_rights_t before insert or update on works for each row execute function works_rights_required();

-- =====================================================================
-- שלב 12: קישור הצטרפות אישי. נשמר למייל אחד ומשמש פעם אחת (אלא אם המנהל קבע אחרת)
-- =====================================================================
alter table org_invites add column if not exists email text;
alter table org_invites add column if not exists max_uses int default 1;
alter table org_invites drop constraint if exists org_invites_max_uses_chk;
alter table org_invites add constraint org_invites_max_uses_chk check (max_uses is null or max_uses between 1 and 500);

create or replace function join_org(p_token text) returns boolean
language plpgsql security definer set search_path = public, auth as $$
declare i org_invites; em text; ok_mail boolean;
begin
  select * into i from org_invites where token = p_token and not revoked and expires_at > now() for update;
  if not found then return false; end if;
  if i.max_uses is not null and i.uses >= i.max_uses then raise exception 'הקישור כבר נוצל. מבקשים קישור חדש ממנהל המערכת'; end if;
  select lower(email), email_confirmed_at is not null into em, ok_mail from auth.users where id = auth.uid();
  if not coalesce(ok_mail, false) then raise exception 'צריך לאשר את כתובת המייל לפני ההצטרפות'; end if;
  if i.email is not null and lower(trim(i.email)) <> em then raise exception 'הקישור הזה אישי, ושייך לכתובת מייל אחרת'; end if;
  perform set_config('app.bypass', '1', true);
  update profiles set role = i.role, status = 'active', org_id = i.org_id
  where id = auth.uid() and role is null and status = 'pending';
  if not found then return false; end if;
  update org_invites set uses = uses + 1 where token = p_token;
  if i.role::text = 'artist' and not exists (select 1 from artists where user_id = auth.uid()) then
    insert into artists (user_id, gallery_id, name)
    values (auth.uid(), i.org_id, coalesce((select full_name from profiles where id = auth.uid()), 'אמן'));
    perform set_config('app.bypass', '1', true);
    update profiles set org_id = null where id = auth.uid();
  end if;
  return true;
end $$;
grant execute on function join_org(text) to authenticated;

-- =====================================================================
-- שלב 13: מנוע אחד, שלושה ערוצים (Grape Arts)
--   כרטיס נוסע ושיוך נעול · קונים עסקיים · יקבים שותפים ומלאי
--   מארזים ורמות · השתתפות אמן והסכמת גלריה · מסגרת תווית
--   סדרות ומהדורות, מרשם קבוע ותעודות · הזמנה חיצונית והצעת מחיר
--   ביקורי סטודיו · טיוטות לשיתוף · קטלוג ציבורי ואימות תעודה
-- =====================================================================

update organizations set name = 'Grape Arts' where kind = 'admin' and name = 'סדנת התווית';

-- ---------- 13.1 כרטיס הנוסע ----------
alter table profiles add column if not exists acq_channel text;
alter table profiles add column if not exists acq_ref text;
alter table profiles add column if not exists acq_at timestamptz;
alter table profiles drop constraint if exists profiles_acq_channel_check;
alter table profiles add constraint profiles_acq_channel_check
  check (acq_channel is null or acq_channel in ('winery_link','invite','direct','admin'));

update profiles set acq_channel = 'winery_link', acq_at = created_at
  where acq_channel is null and role::text = 'customer' and org_id is not null;
update profiles set acq_channel = 'invite', acq_at = created_at
  where acq_channel is null and role is not null and role::text <> 'customer';

-- המקור נקבע פעם אחת. לקוח של יקב עובר ליקב אחר רק על ידי המנהל, והמעבר נרשם ביומן
create or replace function guard_card() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.acq_channel is not null and (new.acq_channel is distinct from old.acq_channel
     or new.acq_ref is distinct from old.acq_ref or new.acq_at is distinct from old.acq_at) then
    raise exception 'מקור ההצטרפות של משתמש לא משתנה';
  end if;
  if old.role::text = 'customer' and new.org_id is distinct from old.org_id then
    if not is_admin() and auth.uid() is not null then
      raise exception 'רק מנהל המערכת מעביר לקוח בין יקבים';
    end if;
    insert into audit_log (action, entity, entity_id, data)
    values ('customer_transfer', 'profile', new.id::text,
            jsonb_build_object('from', old.org_id, 'to', new.org_id, 'reason', current_setting('app.reason', true)));
  end if;
  return new;
end $$;
drop trigger if exists profiles_card on profiles;
create trigger profiles_card before update on profiles for each row execute function guard_card();

create or replace function customer_transfer(p_user uuid, p_winery uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then raise exception 'רק מנהל המערכת מעביר לקוח'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'צריך לכתוב למה מעבירים'; end if;
  if p_winery is not null and not exists (select 1 from organizations where id = p_winery and kind = 'winery') then
    raise exception 'היקב לא נמצא'; end if;
  perform set_config('app.reason', left(p_reason, 300), true);
  update profiles set org_id = p_winery where id = p_user and role::text = 'customer';
  if not found then raise exception 'הלקוח לא נמצא'; end if;
end $$;
grant execute on function customer_transfer(uuid, uuid, text) to authenticated;

-- הצטרפות דרך קישור של יקב: הכניסה הראשונה קובעת
create or replace function join_as_customer(p_slug text) returns boolean
language plpgsql security definer set search_path = public as $$
declare w uuid;
begin
  select id into w from organizations where slug = p_slug and kind = 'winery' and active;
  if w is null then return false; end if;
  perform set_config('app.bypass', '1', true);
  update profiles set role = 'customer', status = 'active', org_id = w,
         acq_channel = coalesce(acq_channel, 'winery_link'), acq_ref = coalesce(acq_ref, p_slug), acq_at = coalesce(acq_at, now())
  where id = auth.uid() and role is null and status = 'pending';
  return found;
end $$;
grant execute on function join_as_customer(text) to authenticated;

-- הצטרפות ישירה, כלקוח של המערכת
create or replace function join_direct(p_ref text default null) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  perform set_config('app.bypass', '1', true);
  update profiles set role = 'customer', status = 'active', org_id = null,
         acq_channel = coalesce(acq_channel, 'direct'), acq_ref = coalesce(acq_ref, left(nullif(p_ref, ''), 60)), acq_at = coalesce(acq_at, now())
  where id = auth.uid() and role is null and status = 'pending';
  return found;
end $$;
grant execute on function join_direct(text) to authenticated;

-- קישור צוות: כמו בשלב 12, ובנוסף נרשם המקור
create or replace function join_org(p_token text) returns boolean
language plpgsql security definer set search_path = public, auth as $$
declare i org_invites; em text; ok_mail boolean;
begin
  select * into i from org_invites where token = p_token and not revoked and expires_at > now() for update;
  if not found then return false; end if;
  if i.max_uses is not null and i.uses >= i.max_uses then raise exception 'הקישור כבר נוצל. מבקשים קישור חדש ממנהל המערכת'; end if;
  select lower(email), email_confirmed_at is not null into em, ok_mail from auth.users where id = auth.uid();
  if not coalesce(ok_mail, false) then raise exception 'צריך לאשר את כתובת המייל לפני ההצטרפות'; end if;
  if i.email is not null and lower(trim(i.email)) <> em then raise exception 'הקישור הזה אישי, ושייך לכתובת מייל אחרת'; end if;
  perform set_config('app.bypass', '1', true);
  update profiles set role = i.role, status = 'active', org_id = i.org_id,
         acq_channel = coalesce(acq_channel, 'invite'), acq_ref = coalesce(acq_ref, left(p_token, 8)), acq_at = coalesce(acq_at, now())
  where id = auth.uid() and role is null and status = 'pending';
  if not found then return false; end if;
  update org_invites set uses = uses + 1 where token = p_token;
  if i.role::text = 'artist' and not exists (select 1 from artists where user_id = auth.uid()) then
    insert into artists (user_id, gallery_id, name)
    values (auth.uid(), i.org_id, coalesce((select full_name from profiles where id = auth.uid()), 'אמן'));
    perform set_config('app.bypass', '1', true);
    update profiles set org_id = null where id = auth.uid();
  end if;
  return true;
end $$;
grant execute on function join_org(text) to authenticated;

-- ---------- 13.2 קונים עסקיים ----------
create table if not exists buyers (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (length(name) between 2 and 120),
  kind       text not null check (kind in ('company','restaurant','hotel','other')),
  vat_id     text check (vat_id is null or length(vat_id) <= 20),
  created_by uuid default auth.uid() references profiles(id),
  created_at timestamptz not null default now()
);
alter table buyers enable row level security;
alter table profiles add column if not exists buyer_id uuid references buyers(id);
drop policy if exists buyers_read on buyers;
create policy buyers_read on buyers for select to authenticated using (
  is_admin() or id = (select buyer_id from profiles where id = auth.uid()));

create or replace function my_card() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'channel', case when p.role::text = 'customer' and p.org_id is not null then 'winery_customer'
                    when p.role::text = 'customer' then 'direct'
                    else coalesce(p.role::text, 'guest') end,
    'owner_winery', case when p.role::text = 'customer' then p.org_id end,
    'owner_name', (select o.name from organizations o where o.id = p.org_id and p.role::text = 'customer'),
    'price_book', case when p.role::text = 'customer' and p.org_id is not null then 'winery' else 'platform' end,
    'buyer', (select jsonb_build_object('id', b.id, 'name', b.name, 'kind', b.kind) from buyers b where b.id = p.buyer_id),
    'acq', p.acq_channel, 'acq_ref', p.acq_ref, 'acq_at', p.acq_at)
  from profiles p where p.id = auth.uid()
$$;
grant execute on function my_card() to authenticated;

-- ---------- 13.3 יקבים שותפים ומלאי בקבוקים בלי תווית ----------
alter table organizations add column if not exists partner boolean not null default false;
alter table organizations add column if not exists kosher boolean not null default false;
alter table wines add column if not exists direct boolean not null default false;
alter table wines add column if not exists direct_price numeric check (direct_price is null or direct_price > 0);
alter table wines add column if not exists cost_price numeric check (cost_price is null or cost_price >= 0);
alter table wines add column if not exists shiners int not null default 0;
alter table wines add column if not exists drink_by int;
alter table wines drop constraint if exists wines_shiners_check;
alter table wines add constraint wines_shiners_check check (shiners >= 0);

-- ---------- 13.4 מארזים ורמות ----------
create table if not exists packages (
  id       bigint generated by default as identity primary key,
  code     text not null unique,
  name     text not null,
  level    text not null check (level in ('case','collector','patron')),
  bottles  int  not null check (bottles between 1 and 12),
  box      text,
  price    numeric not null default 0 check (price >= 0),   -- המארז עצמו, בלי היין, לפני מע״מ
  includes jsonb not null default '{}',
